#[cfg(test)]
thread_local! {
    static TEST_ROUTE_MATERIALIZATION_COUNT: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn reset_test_route_materialization_count() {
    TEST_ROUTE_MATERIALIZATION_COUNT.with(|count| count.set(0));
}

#[cfg(test)]
pub(crate) fn test_route_materialization_count() -> usize {
    TEST_ROUTE_MATERIALIZATION_COUNT.with(std::cell::Cell::get)
}

/// The already-admitted production island whose materialization failed or
/// lacked its canonical operation receipt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CanonicalMirRouteProfile {
    MapRoot,
    MapAnyOwnerV1,
    OrdinaryMapOwnedAnyV2,
    OrdinaryMapOwnedAnyV2DirectPrint,
    OrdinaryMapOwnedAnyV2GetOrDefaultI32,
    OrdinaryMapOwnedAnyV2GetOrDefaultString,
    OrdinaryMapOwnedAnyV2CheckedGet,
    OrdinaryMapOwnedAnyV2ComputedKeyGet,
    OrdinaryMapOwnedAnyV2ComputedStringKeyOwnerChain,
    OrdinaryMapOwnedAnyV2DynamicKeysGet,
    OrdinaryMapOwnedAnyV2ZeroMissI32,
    OrdinaryMapOwnedAnyV2RemovedKeyCheckedMiss,
    OrdinaryMapOwnedAnyV2ValuesFieldMove,
    OrdinaryMapOwnedAnyV2ValuesLocalIndexI32,
    OrdinaryMapOwnedAnyV2ValuesHeterogeneousStringIndex1,
    OrdinaryMapOwnedAnyV2ValuesSnapshotReplacement,
    OrdinaryMapOwnedAnyV2ValuesMixedSnapshot,
    OrdinaryMapOwnedAnyV2ValuesMixedSnapshotRemove,
    OrdinaryMapOwnedAnyV2KeysSnapshot,
    OrdinaryMapOwnedAnyV2ValuesProducerCaller,
    OrdinaryMapOwnedAnyV2ValuesCrosscallStringCaller,
    OrdinaryMapOwnedAnyV2ValuesCrosscallStringCallerIndex1,
    OrdinaryMapOwnedAnyV2MapRootProducerCaller,
    OrdinaryMapOwnedAnyV2MapRootGetAnyCaller,
    OrdinaryMapOwnedAnyV2IsEmpty,
    OrdinaryMapOwnedAnyV2RecordUnit,
    OrdinaryMapOwnedAnyV2MapSetDropControl,
    OrdinaryMapOwnedAnyV2BranchLocalSetDiamond,
    OrdinaryMapOwnedAnyV2CloneIsolation,
    OrdinaryMapOwnedAnyV2PersistentRootAliasReplacement,
    MapEmptyRootRootQueriesV1,
    OrdinaryMapOwnerLifecycleI32StringV1,
    OrdinaryMapOwnerLifecycleObserverV1,
    OrdinaryMapOwnedGetI32StringV1,
    ScalarExport,
    ScalarFfi,
    ScalarNested,
    ScalarActor,
    ScalarGenericIdentityI32,
    ScalarGenericIdentityI64,
    ScalarCollection,
    FlatCopyRecord,
    S8FlowTransition,
    FlowFailureRetry,
    NonCopyOptionStringVariant,
    NonCopyOptionNestedTupleVariant,
    GenericOptionPredicate,
    GenericOptionProjection,
    GenericOptionProjectionFallback,
    GenericResultProjection,
    GenericResultProjectionFallback,
    ManagedResultCall,
    CopyOptionI32Variant,
    CopyOptionBoolVariant,
    CopyOptionI64Variant,
    CopyOptionF64Variant,
    CopyResultI32Variant,
    SessionChannel,
}

