/// Validate the source-derived Checker admission and the exact Core/MIR
/// snapshot/replacement witness. The broad V2 production-readiness constant
/// is intentionally not consulted or changed by this narrow route.
pub fn validate_ordinary_map_owned_any_v2_values_snapshot_replacement_route(
    checked: &CheckedProgram,
    canonical: &MirProgram,
) -> Result<(), String> {
    if classify_ordinary_map_owned_any_v2_admission(checked)
        != OrdinaryMapOwnedAnyV2Admission::ValuesSnapshotReplacement
    {
        return Err("Checker did not admit the exact Values snapshot replacement profile".into());
    }
    let owner = crate::core::NodeId("function:main".into());
    let checker_receipts = checked
        .resource_analysis(&owner)
        .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
        .map(|receipt| receipt.values_snapshot_replacement_receipts.as_slice())
        .ok_or_else(|| "CheckedProgram has no Values snapshot replacement receipt".to_string())?;
    let mir_receipts =
        canonical.ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()?;
    if checker_receipts.len() != 1
        || mir_receipts.len() != 1
        || mir_receipts[0].owner != owner
        || mir_receipts[0].checker != checker_receipts[0]
    {
        return Err(
            "CheckedProgram and MIR do not carry the same exact Values snapshot replacement receipt"
                .into(),
        );
    }
    validate_ordinary_map_owned_any_v2_values_unpack_receipts(checked, canonical)?;
    validate_ordinary_map_owned_any_v2_values_snapshot_replacement_mir_route(canonical)
}

/// MIR-only half of the snapshot replacement route. It rederives the witness
/// from the embedded private Checker receipt and the complete canonical graph
/// so raw MIR cannot manufacture this route from a profile string.
pub fn validate_ordinary_map_owned_any_v2_values_snapshot_replacement_mir_route(
    canonical: &MirProgram,
) -> Result<(), String> {
    validate_ordinary_map_owned_any_v2_island(canonical)
        .map_err(|errors| format!("whole-program V2 island rejected: {errors:?}"))?;
    let receipts = canonical.ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()?;
    if receipts.len() != 1 {
        return Err(format!(
            "Values snapshot replacement requires exactly one independently derived Core/MIR witness, found {}",
            receipts.len()
        ));
    }
    receipts[0].validate_against_program(canonical)?;

    let values = canonical.ordinary_map_owned_any_v2_values_result_receipts()?;
    let unpacks = canonical.ordinary_map_owned_any_v2_values_unpack_result_receipts()?;
    let selection = canonical
        .ordinary_map_owned_any_v2_payload_selection_receipt()?
        .ok_or_else(|| {
            "Values snapshot replacement has no payload selection witness".to_string()
        })?;
    if values.len() != 1
        || unpacks.len() != 2
        || selection.entries.len() != 3
        || !canonical
            .ordinary_map_owned_any_v2_get_any_result_receipts()?
            .is_empty()
        || !canonical
            .ordinary_map_owned_any_v2_unpack_result_receipts()?
            .is_empty()
    {
        return Err(
            "Values snapshot replacement requires one snapshot, two exact indexed unpacks, three selected Set payloads, and no GetAny graph".into(),
        );
    }
    Ok(())
}

