    #[test]
    fn keys_snapshot_mir_route_rejects_tampered_set_payload_typedesc() {
        let checked = checked(
            r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let key = snapshot[0]
    drop(snapshot)
    println(key)
    drop(key)
    0
}
"#,
        );
        let mut canonical = MirProgram::from_checked_program(&checked)
            .expect("exact KeysSnapshot source lowers to MIR");
        let owner = NodeId("function:main".into());
        let mut function = canonical
            .functions()
            .get(&owner)
            .expect("main function")
            .clone();
        let set_value = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                MirInstructionKind::OrdinaryMapOwnedAnyV2Set { value, .. } => Some(value.clone()),
                _ => None,
            })
            .expect("Set payload value");
        function
            .values
            .get_mut(&set_value)
            .expect("Set payload MIR value")
            .ty = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I64);
        canonical.replace_function_for_test_only(function);

        let error = validate_ordinary_map_owned_any_v2_keys_snapshot_mir_route(&canonical)
            .expect_err("MIR payload TypeDesc cannot disagree with the Checker action");
        assert!(
            error.contains("KeysSnapshot MIR island rejected") && error.contains("ManagedAny"),
            "the MIR island must reject a forged Set payload TypeDesc before route materialization: {error}"
        );
    }

    #[test]
    fn keys_snapshot_composes_only_with_its_exact_checked_source_receipt() {
        const SOURCE: &str = r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let key = snapshot[0]
    drop(snapshot)
    println(key)
    drop(key)
    0
}
"#;

        let program = checked(SOURCE);
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::KeysSnapshot
        );
        assert_eq!(
            admission.collection,
            ScalarCollectionAdmission::MixedCoverage,
            "the scalar-collection scanner sees key output beside managed Map ownership"
        );

        let canonical = MirProgram::from_checked_program(&program)
            .expect("exact KeysSnapshot source lowers to MIR");
        let receipt = validate_ordinary_map_owned_any_v2_keys_snapshot_route(&program, &canonical)
            .expect("the exact checked-source route must produce its receipt");
        assert_eq!(
            receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_KEYS_SNAPSHOT_PROFILE
        );
        receipt
            .validate_against_program(&canonical)
            .expect("the exact KeysSnapshot receipt binds to this canonical MIR");

        let route = materialize_canonical_mir_route(&program, None)
            .expect("the exact receipted KeysSnapshot route may compose with its key output");
        assert_eq!(
            route.ordinary_map_owned_any_v2_keys_snapshot_route_receipt,
            Some(receipt.clone()),
            "materialization reuses the receipt validated before the composition gate"
        );
        assert!(!route.materialized_collection_operation_candidate);

        let reasons_for = |receipt: Option<&CanonicalMirRouteReceipt>, operation_candidate| {
            unsupported_map_root_composition_reasons(
                admission,
                operation_candidate,
                false,
                false,
                false,
                false,
                false,
                false,
                false,
                receipt,
                None,
                &canonical,
            )
        };
        assert!(!reasons_for(Some(&receipt), false).contains(&"mixed scalar-collection admission"));

        assert!(reasons_for(None, false).contains(&"mixed scalar-collection admission"));

        let mut wrong_profile = receipt.clone();
        wrong_profile.profile = "some-other-route-v1".into();
        assert!(
            reasons_for(Some(&wrong_profile), false).contains(&"mixed scalar-collection admission")
        );

        let other_program = checked(&SOURCE.replace("41", "42"));
        let other_canonical = MirProgram::from_checked_program(&other_program)
            .expect("changed KeysSnapshot source lowers to MIR");
        let stale_receipt =
            other_canonical.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_KEYS_SNAPSHOT_PROFILE);
        assert!(stale_receipt.validate_against_program(&canonical).is_err());
        assert!(
            reasons_for(Some(&stale_receipt), false).contains(&"mixed scalar-collection admission")
        );

        let operation_candidate = reasons_for(Some(&receipt), true);
        assert!(operation_candidate.contains(&"materialized List/Set operation"));
        assert!(operation_candidate.contains(&"mixed scalar-collection admission"));

        let unrelated_stdout =
            SOURCE.replace("    println(key)\n", "    println(key)\n    println(0)\n");
        let unrelated_program = checked(&unrelated_stdout);
        assert_ne!(
            classify_canonical_mir_route_admission(&unrelated_program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::KeysSnapshot,
            "an unrelated print must invalidate exact KeysSnapshot source admission"
        );
        assert!(materialize_canonical_mir_route(&unrelated_program, None).is_err());
    }

    #[test]
    fn dynamic_keys_get_composition_requires_its_semantic_mir_receipt() {
        const SOURCE: &str = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_dynamic_keys_get.mimi"
        );

        let program = checked(SOURCE);
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::DynamicKeysGet
        );
        assert_eq!(
            admission.collection,
            ScalarCollectionAdmission::MixedCoverage
        );

        let canonical = MirProgram::from_checked_program(&program)
            .expect("exact DynamicKeysGet source lowers to MIR");
        let receipt =
            validate_ordinary_map_owned_any_v2_dynamic_keys_get_route(&program, &canonical)
                .expect("the exact checked-source route produces its receipt");
        let reasons_for = |canonical: &MirProgram,
                           receipt: Option<&CanonicalMirRouteReceipt>,
                           operation_candidate| {
            unsupported_map_root_composition_reasons(
                admission,
                operation_candidate,
                false,
                false,
                false,
                false,
                false,
                false,
                false,
                None,
                receipt,
                canonical,
            )
        };
        assert!(
            !reasons_for(&canonical, Some(&receipt), false)
                .contains(&"mixed scalar-collection admission"),
            "the exact semantic DynamicKeysGet receipt clears only its owned scalar tail"
        );
        let materialized = materialize_canonical_mir_route(&program, None)
            .expect("the exact DynamicKeysGet profile composes with its scalar result");
        assert!(materialized
            .ordinary_map_owned_any_v2_dynamic_keys_get_route_receipt
            .is_some());

        assert!(reasons_for(&canonical, None, false).contains(&"mixed scalar-collection admission"));
        let mut wrong_profile = receipt.clone();
        wrong_profile.profile = "some-other-route-v1".into();
        assert!(reasons_for(&canonical, Some(&wrong_profile), false)
            .contains(&"mixed scalar-collection admission"));

        let unrelated = checked("func main() -> bool { println(true) true }");
        let unrelated_mir = MirProgram::from_checked_program(&unrelated)
            .expect("unrelated scalar source lowers to MIR");
        assert!(receipt.validate_against_program(&unrelated_mir).is_err());
        assert!(reasons_for(&unrelated_mir, Some(&receipt), false)
            .contains(&"mixed scalar-collection admission"));

        // A profile string plus a fresh graph digest is not a semantic route
        // receipt. Generic receipts are structurally valid for any profile;
        // the DynamicKeysGet MIR validator supplies the missing authority.
        let forged_profile =
            unrelated_mir.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_DYNAMIC_KEYS_GET_PROFILE);
        forged_profile
            .validate_against_program(&unrelated_mir)
            .expect("the generic digest receipt is structurally valid");
        assert!(
            validate_ordinary_map_owned_any_v2_dynamic_keys_get_mir_route(&unrelated_mir).is_err()
        );
        assert!(reasons_for(&unrelated_mir, Some(&forged_profile), false)
            .contains(&"mixed scalar-collection admission"));

        let operation_reasons = reasons_for(&canonical, Some(&receipt), true);
        assert!(operation_reasons.contains(&"materialized List/Set operation"));
        assert!(operation_reasons.contains(&"mixed scalar-collection admission"));
    }

