    #[test]
    fn ordinary_map_owned_any_v2_map_set_drop_control_is_exact_and_isolated() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_v2_map_set_drop_control.mimi"
        );
        let checked_with_prelude = |source: &str| {
            let tokens = crate::lexer::Lexer::new(source).tokenize().expect("lex");
            let mut file = crate::parser::Parser::new(tokens)
                .parse_file()
                .expect("parse");
            crate::loader::merge_prelude_into(&mut file);
            crate::core::check_program(&file).expect("typecheck with prelude")
        };
        let program = checked(source);
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl
        );

        let route = materialize_canonical_mir_route(&program, None)
            .expect("the exact no-query control source materializes");
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2MapSetDropControl;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert!(route.materialized_ordinary_map_owned_any_v2_map_set_drop_control_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_is_empty_candidate);
        assert!(route
            .ordinary_map_owned_any_v2_is_empty_route_receipt
            .is_none());
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
        validate_ordinary_map_owned_any_v2_map_set_drop_control_route(&program, &route.program)
            .expect("the Checker and MIR ownership proofs bind");
        let receipt = route
            .ordinary_map_owned_any_v2_map_set_drop_control_route_receipt
            .as_ref()
            .expect("the independent route receipt is present");
        assert_eq!(
            receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_MAP_SET_DROP_CONTROL_PROFILE
        );
        receipt
            .validate_against_program(&route.program)
            .expect("the route receipt covers the materialized graph");

        let control_selection = route
            .ordinary_map_owned_any_v2_payload_selection
            .as_ref()
            .expect("the Set payload selection is receipted");
        assert_eq!(control_selection.entries.len(), 1);
        assert_eq!(control_selection.selected_types.len(), 1);
        let is_empty_program = checked(include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_v2_is_empty.mimi"
        ));
        let is_empty_route = materialize_canonical_mir_route(&is_empty_program, None)
            .expect("the IsEmpty comparison fixture materializes independently");
        let is_empty_selection = is_empty_route
            .ordinary_map_owned_any_v2_payload_selection
            .as_ref()
            .expect("the IsEmpty Set payload selection is receipted");
        assert_eq!(
            control_selection.selected_types[0].type_id,
            is_empty_selection.selected_types[0].type_id
        );
        assert_eq!(
            control_selection.selected_types[0].type_desc_digest,
            is_empty_selection.selected_types[0].type_desc_digest
        );
        assert_eq!(
            control_selection.entries[0].checker_type,
            is_empty_selection.entries[0].checker_type
        );
        assert_eq!(
            control_selection.entries[0].mir_type,
            is_empty_selection.entries[0].mir_type
        );
        assert_eq!(
            control_selection.entries[0].type_desc_digest,
            is_empty_selection.entries[0].type_desc_digest
        );

        let prelude_program = checked_with_prelude(source);
        let prelude_admission = classify_canonical_mir_route_admission(&prelude_program);
        assert_eq!(
            prelude_admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl,
            "only the canonical prelude may extend the narrow single-main source graph"
        );
        let prelude_route = materialize_canonical_mir_route(&prelude_program, None)
            .expect("the exact no-query control source materializes with the CLI prelude");
        validate_ordinary_map_owned_any_v2_map_set_drop_control_route(
            &prelude_program,
            &prelude_route.program,
        )
        .expect("prelude callables remain outside the canonical owner graph");

        let source_with_user_callable = format!("func unrelated() -> i32 {{ 7 }}\n{source}");
        let extra_callable_program = checked_with_prelude(&source_with_user_callable);
        assert_ne!(
            classify_canonical_mir_route_admission(&extra_callable_program)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl,
            "a second user callable must not be hidden by excluding the canonical prelude"
        );

        let mut reordered_roots = route.program.clone();
        mutate_main_mir(&mut reordered_roots, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let root_drop_indices = block
                .instructions
                .iter()
                .enumerate()
                .filter_map(|(index, instruction)| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { .. }
                    )
                    .then_some(index)
                })
                .collect::<Vec<_>>();
            assert_eq!(root_drop_indices.len(), 2);
            block
                .instructions
                .swap(root_drop_indices[0], root_drop_indices[1]);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_map_set_drop_control_mir_route(&reordered_roots)
                .is_err(),
            "the MIR-only validator rejects a changed old/new root Drop order"
        );
        assert!(
            validate_ordinary_map_owned_any_v2_map_set_drop_control_route(
                &program,
                &reordered_roots
            )
            .is_err(),
            "the checked route rejects a changed root Drop order"
        );

        let mut missing_set_clone_drop = route.program.clone();
        mutate_main_mir(&mut missing_set_clone_drop, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let set_payload = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { value, .. } => {
                        Some(value.clone())
                    }
                    _ => None,
                })
                .expect("MapSetDropControl Set payload");
            let drop_index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(&instruction.kind, MirInstructionKind::Drop { value } if value == &set_payload)
                })
                .expect("Set temporary clone Drop");
            block.instructions.remove(drop_index);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_map_set_drop_control_mir_route(
                &missing_set_clone_drop
            )
            .is_err(),
            "the MIR-only validator rejects a missing Set temporary clone Drop"
        );

        let mut duplicate_set_clone_drop = route.program.clone();
        mutate_main_mir(&mut duplicate_set_clone_drop, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let set_payload = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { value, .. } => {
                        Some(value.clone())
                    }
                    _ => None,
                })
                .expect("MapSetDropControl Set payload");
            let drop_index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(&instruction.kind, MirInstructionKind::Drop { value } if value == &set_payload)
                })
                .expect("Set temporary clone Drop");
            let duplicate = block.instructions[drop_index].clone();
            block.instructions.insert(drop_index + 1, duplicate);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_map_set_drop_control_mir_route(
                &duplicate_set_clone_drop
            )
            .is_err(),
            "the MIR-only validator rejects a duplicate Set temporary clone Drop"
        );

        let mut reordered_payload_drops = route.program.clone();
        mutate_main_mir(&mut reordered_payload_drops, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let drop_indices = block
                .instructions
                .iter()
                .enumerate()
                .filter_map(|(index, instruction)| {
                    matches!(&instruction.kind, MirInstructionKind::Drop { .. }).then_some(index)
                })
                .collect::<Vec<_>>();
            assert_eq!(drop_indices.len(), 3);
            block.instructions.swap(drop_indices[1], drop_indices[2]);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_map_set_drop_control_mir_route(
                &reordered_payload_drops
            )
            .is_err(),
            "the MIR-only validator rejects source-payload settlement before the Set clone"
        );

        let with_query = source.replace(
            "    let populated = map_set(empty, \"payload\", payload)",
            "    let observed = is_empty(empty)\n    let populated = map_set(empty, \"payload\", payload)",
        );
        assert_ne!(
            with_query, source,
            "the control fixture contains the Set marker"
        );
        let with_query = checked(&with_query);
        assert_ne!(
            classify_canonical_mir_route_admission(&with_query).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl,
            "an inserted IsEmpty query is outside the no-query profile"
        );
        assert!(
            materialize_canonical_mir_route(&with_query, None).is_err(),
            "the inserted query fails closed at route materialization"
        );

        let with_print = source.replace("    drop(empty)", "    println(7)\n    drop(empty)");
        assert_ne!(
            with_print, source,
            "the control fixture contains the root Drop marker"
        );
        let with_print = checked(&with_print);
        assert_ne!(
            classify_canonical_mir_route_admission(&with_print).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl,
            "inserted stdout is outside the no-query control profile"
        );
        assert!(
            materialize_canonical_mir_route(&with_print, None).is_err(),
            "inserted output fails closed at route materialization"
        );

        let with_reversed_root_drops = source.replace(
            "    drop(empty)\n    drop(populated)",
            "    drop(populated)\n    drop(empty)",
        );
        assert_ne!(with_reversed_root_drops, source);
        let with_reversed_root_drops = checked(&with_reversed_root_drops);
        assert_ne!(
            classify_canonical_mir_route_admission(&with_reversed_root_drops)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::MapSetDropControl,
            "reversing the root Drops is outside the exact lineage profile"
        );
        assert!(
            materialize_canonical_mir_route(&with_reversed_root_drops, None).is_err(),
            "reversed root Drops fail closed at route materialization"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_is_empty_has_an_exact_non_global_route() {
        let source = include_str!("../../../tests/fixtures/mir_ordinary_map_any_v2_is_empty.mimi");
        let program = checked(source);
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IsEmpty
        );

        let route = materialize_canonical_mir_route(&program, None)
            .expect("the exact IsEmpty source fixture materializes");
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2IsEmpty;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert!(route.materialized_ordinary_map_owned_any_v2_is_empty_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
        validate_ordinary_map_owned_any_v2_is_empty_route(&program, &route.program)
            .expect("the Checker and MIR proofs bind");
        let receipt = route
            .ordinary_map_owned_any_v2_is_empty_route_receipt
            .as_ref()
            .expect("the dedicated route receipt is present");
        assert_eq!(receipt.profile, ORDINARY_MAP_OWNED_ANY_V2_IS_EMPTY_PROFILE);
        receipt
            .validate_against_program(&route.program)
            .expect("the dedicated route receipt matches the materialized graph");
        assert!(route
            .ordinary_map_owned_any_v2_payload_selection
            .as_ref()
            .is_some_and(|selection| selection.entries.len() == 1));

        let mut changed_return = route.program.clone();
        mutate_main_mir(&mut changed_return, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let returned = match &block.terminator {
                crate::core::mir::MirTerminator::Return { value: Some(value) } => value.clone(),
                _ => panic!("IsEmpty fixture returns an i32 value"),
            };
            let constant = block
                .instructions
                .iter_mut()
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::Const { result, .. } if result == &returned
                    )
                })
                .expect("return value has a constant definition");
            let MirInstructionKind::Const { literal, .. } = &mut constant.kind else {
                unreachable!();
            };
            *literal = crate::core::ir::ResolvedLiteral::Int(1);
        });
        let resealed_return =
            changed_return.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_IS_EMPTY_PROFILE);
        resealed_return
            .validate_against_program(&changed_return)
            .expect("the changed graph can carry a self-consistent digest");
        assert!(
            validate_ordinary_map_owned_any_v2_is_empty_mir_route(&changed_return).is_err(),
            "a re-sealed MIR with a different return value is outside the exact source profile"
        );

        let mut recursive_call = route.program.clone();
        mutate_main_mir(&mut recursive_call, |main| {
            let result = super::super::MirValueId::new("value:forged-is-empty-recursive-call")
                .expect("fresh call result identity");
            main.values.insert(
                result.clone(),
                crate::core::mir::MirValue {
                    id: result.clone(),
                    ty: main.result.clone(),
                },
            );
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            block.instructions.insert(
                0,
                crate::core::mir::MirInstruction {
                    id: crate::core::mir::MirInstructionId::new(
                        "inst:forged-is-empty-recursive-call",
                    )
                    .expect("fresh call instruction identity"),
                    kind: MirInstructionKind::Call {
                        result: Some(result),
                        callee: crate::core::ir::ResolvedCallee::Function(NodeId(
                            "function:main".into(),
                        )),
                        type_arguments: Vec::new(),
                        arguments: Vec::new(),
                        effect_receipts: Vec::new(),
                        variant_call_contract: None,
                    },
                },
            );
        });
        let resealed_recursive_call =
            recursive_call.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_IS_EMPTY_PROFILE);
        resealed_recursive_call
            .validate_against_program(&recursive_call)
            .expect("the recursive graph can carry a self-consistent receipt");
        let recursive_source_pair = validate_checked_mir_source_pair(
            &program,
            &recursive_call,
            &NodeId("function:main".into()),
            "IsEmpty",
        )
        .expect_err("independent lowering must reject the injected recursive call");
        assert!(recursive_source_pair.contains("semantics differ"));
        assert!(
            validate_ordinary_map_owned_any_v2_is_empty_route(&program, &recursive_call).is_err(),
            "the checked route rejects a re-sealed MIR that injects an unreceipted recursive call"
        );

        let mut early_payload_drop = route.program.clone();
        mutate_main_mir(&mut early_payload_drop, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let (populated_root, set_value) = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { result, value, .. } => {
                        Some((result.clone(), value.clone()))
                    }
                    _ => None,
                })
                .expect("persistent Set instruction");
            let payload_source = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::Clone { result, source } if result == &set_value => {
                        Some(source.clone())
                    }
                    _ => None,
                })
                .expect("Set payload has a Checker-lowered owned clone");
            let drop_index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::Drop { value } if value == &payload_source
                    )
                })
                .expect("source payload has its explicit Drop");
            let payload_drop = block.instructions.remove(drop_index);
            let second_query_index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2IsEmpty { root, .. }
                            if root == &populated_root
                    )
                })
                .expect("IsEmpty query for the populated root");
            block.instructions.insert(second_query_index, payload_drop);
        });
        let resealed_early_payload_drop =
            early_payload_drop.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_IS_EMPTY_PROFILE);
        resealed_early_payload_drop
            .validate_against_program(&early_payload_drop)
            .expect("the early-drop graph can carry a self-consistent receipt");
        let early_drop_source_pair = validate_checked_mir_source_pair(
            &program,
            &early_payload_drop,
            &NodeId("function:main".into()),
            "IsEmpty",
        )
        .expect_err("independent lowering must reject the reordered payload Drop");
        assert!(early_drop_source_pair.contains("semantics differ"));
        assert!(
            validate_ordinary_map_owned_any_v2_is_empty_route(&program, &early_payload_drop)
                .is_err(),
            "the checked route rejects a re-sealed MIR that moves payload Drop ahead of the second query"
        );

        let with_extra_map_operation = source.replace(
            "    drop(empty)",
            "    println(map_size(populated))\n    drop(empty)",
        );
        let program = checked(&with_extra_map_operation);
        assert_ne!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IsEmpty,
            "an extra Map operation cannot compose into the IsEmpty profile"
        );
        assert!(
            materialize_canonical_mir_route(&program, None).is_err(),
            "an extra Map operation remains blocked by the closed broad readiness gate"
        );

        let with_unreceipted_bool_print =
            source.replace("    println(empty_result)", "    println(true)");
        let program = checked(&with_unreceipted_bool_print);
        assert_ne!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IsEmpty,
            "a bool literal print cannot impersonate an IsEmpty result"
        );
        assert!(
            materialize_canonical_mir_route(&program, None).is_err(),
            "unreceipted output cannot use the dedicated production route"
        );

        let with_reordered_query_output = source.replace(
            "    println(empty_result)\n\n    let populated = map_set(empty, \"payload\", payload)",
            "    let populated = map_set(empty, \"payload\", payload)\n    println(empty_result)",
        );
        assert_ne!(
            with_reordered_query_output, source,
            "the source fixture has the expected first-query output marker"
        );
        let program = checked(&with_reordered_query_output);
        assert_ne!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IsEmpty,
            "source admission must reject query output moved across persistent Set"
        );
        assert!(
            materialize_canonical_mir_route(&program, None).is_err(),
            "reordered query output cannot use the exact IsEmpty production route"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_record_unit_is_an_exact_non_global_route() {
        let source =
            include_str!("../../../tests/fixtures/mir_ordinary_map_any_owner_v2_record_unit.mimi");
        let program = checked(source);
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::RecordUnit
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let route = materialize_canonical_mir_route(&program, None)
            .expect("the exact mixed-payload RecordUnit fixture materializes");
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2RecordUnit;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert!(route.materialized_ordinary_map_owned_any_v2_record_unit_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        validate_ordinary_map_owned_any_v2_record_unit_route(&program, &route.program)
            .expect("Checker and MIR receipts bind the exact RecordUnit shape");
        let receipt = route
            .ordinary_map_owned_any_v2_record_unit_route_receipt
            .as_ref()
            .expect("the dedicated RecordUnit route receipt is present");
        assert_eq!(
            receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_RECORD_UNIT_PROFILE
        );
        receipt
            .validate_against_program(&route.program)
            .expect("the route receipt matches the materialized MIR graph");
        let selection = route
            .ordinary_map_owned_any_v2_payload_selection
            .as_ref()
            .expect("the Set payload TypeDesc selection is receipted");
        assert_eq!(selection.entries.len(), 3);
        assert_eq!(selection.selected_types.len(), 2);

        let changed_sources = [
            (
                "missing-size-operation",
                source.replace("    map_size(removed)\n", "    0\n"),
            ),
            (
                "duplicate-size-operation",
                source.replace(
                    "    map_size(removed)\n",
                    "    map_size(removed)\n    map_size(removed)\n",
                ),
            ),
            (
                "wrong-query-root",
                source.replace("has_key(two, \"label\")", "has_key(empty, \"label\")"),
            ),
            (
                "dynamic-key-provenance",
                source.replace(
                    "    has_key(two, \"label\")",
                    "    let key = \"label\"\n    has_key(two, key)",
                ),
            ),
            (
                "different-static-key",
                source.replace("has_key(two, \"label\")", "has_key(two, \"other\")"),
            ),
            (
                "missing-query-action-and-attempt",
                source.replace("    map_size(removed)\n", ""),
            ),
            (
                "duplicate-query-action-and-attempt",
                source.replace(
                    "    map_size(removed)\n",
                    "    map_size(removed)\n    map_size(removed)\n",
                ),
            ),
            (
                "different-scalar-payload",
                source.replace(
                    "map_set(empty, \"answer\", 42)",
                    "map_set(empty, \"answer\", 43)",
                ),
            ),
            (
                "wrong-label-layout",
                source
                    .replace("type Label { text: string }", "type Label { text: i32 }")
                    .replace("text: \"owned label\"", "text: 7"),
            ),
            (
                "wrong-output-source",
                source.replace("println(label.text)", "println(\"owned label\")"),
            ),
            (
                "reordered-root-drops",
                source.replace(
                    "    drop(empty)\n    drop(one)",
                    "    drop(one)\n    drop(empty)",
                ),
            ),
        ];
        for (name, changed_source) in changed_sources {
            assert_ne!(
                changed_source, source,
                "mutation {name} changed the fixture"
            );
            let changed = checked(&changed_source);
            assert_ne!(
                classify_canonical_mir_route_admission(&changed).ordinary_map_owned_any_v2,
                OrdinaryMapOwnedAnyV2Admission::RecordUnit,
                "mutation {name} is outside the exact Checker profile"
            );
            assert!(
                materialize_canonical_mir_route(&changed, None).is_err(),
                "mutation {name} cannot borrow a different or broad production route"
            );
        }

        let mut missing_operation = route.program.clone();
        mutate_main_mir(&mut missing_operation, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Size { .. }
                    )
                })
                .expect("one Size operation");
            block.instructions.remove(index);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&missing_operation).is_err(),
            "the MIR-only validator rejects a missing operation"
        );

        let mut duplicate_operation = route.program.clone();
        mutate_main_mir(&mut duplicate_operation, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let operation = block
                .instructions
                .iter()
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Size { .. }
                    )
                })
                .expect("one Size operation")
                .clone();
            block.instructions.push(operation);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&duplicate_operation).is_err(),
            "the MIR-only validator rejects a duplicated operation"
        );

        let mut missing_attempt = route.program.clone();
        mutate_main_mir(&mut missing_attempt, |main| {
            let receipt = main
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("embedded Checker CFG receipt");
            let attempt = receipt
                .attempts
                .iter()
                .find(|attempt| attempt.kind == crate::core::OrdinaryMapOwnedAnyV2AttemptKind::Size)
                .expect("one Size attempt")
                .clone();
            assert!(
                receipt.attempts.remove(&attempt),
                "remove exactly the selected Size attempt"
            );
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&missing_attempt).is_err(),
            "the MIR-only validator rejects a missing operation attempt"
        );

        let mut duplicate_attempt = route.program.clone();
        mutate_main_mir(&mut duplicate_attempt, |main| {
            let receipt = main
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("embedded Checker CFG receipt");
            let attempt = receipt
                .attempts
                .iter()
                .find(|attempt| attempt.kind == crate::core::OrdinaryMapOwnedAnyV2AttemptKind::Size)
                .expect("one Size attempt")
                .clone();
            let mut attempts = receipt.attempts.clone();
            let duplicate = crate::core::OrdinaryMapOwnedAnyV2Attempt {
                point: crate::core::NodeId(format!("{}:duplicate", attempt.point.0)),
                ..attempt
            };
            assert!(
                attempts.insert(duplicate),
                "insert a distinct extra Size attempt"
            );
            receipt.attempts = attempts;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&duplicate_attempt).is_err(),
            "the MIR-only validator rejects a duplicated operation attempt"
        );

        let mut wrong_root = route.program.clone();
        mutate_main_mir(&mut wrong_root, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let replacement = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { result, .. } => {
                        Some(result.clone())
                    }
                    _ => None,
                })
                .expect("second root identity");
            let size = block
                .instructions
                .iter_mut()
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Size { .. }
                    )
                })
                .expect("one Size operation");
            let MirInstructionKind::OrdinaryMapOwnedAnyV2Size { root, .. } = &mut size.kind else {
                unreachable!();
            };
            *root = replacement;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&wrong_root).is_err(),
            "the MIR-only validator rejects a query on another persistent root"
        );

        let mut wrong_payload = route.program.clone();
        mutate_main_mir(&mut wrong_payload, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let literal = block
                .instructions
                .iter_mut()
                .find_map(|instruction| match &mut instruction.kind {
                    MirInstructionKind::Const { literal, .. }
                        if *literal == crate::core::ir::ResolvedLiteral::Int(42) =>
                    {
                        Some(literal)
                    }
                    _ => None,
                })
                .expect("the first Set payload literal");
            *literal = crate::core::ir::ResolvedLiteral::Int(43);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&wrong_payload).is_err(),
            "the MIR-only validator rejects a changed materialized payload"
        );

        let mut wrong_drops = route.program.clone();
        mutate_main_mir(&mut wrong_drops, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let root_drops = block
                .instructions
                .iter()
                .enumerate()
                .filter_map(|(index, instruction)| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { .. }
                    )
                    .then_some(index)
                })
                .collect::<Vec<_>>();
            assert_eq!(root_drops.len(), 5);
            block.instructions.swap(root_drops[0], root_drops[1]);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&wrong_drops).is_err(),
            "the MIR-only validator rejects reordered root settlement"
        );

        let mut missing_root_drop = route.program.clone();
        mutate_main_mir(&mut missing_root_drop, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { .. }
                    )
                })
                .expect("one root Drop");
            block.instructions.remove(index);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&missing_root_drop).is_err(),
            "the MIR-only validator rejects a missing root settlement"
        );

        let mut duplicate_root_drop = route.program.clone();
        mutate_main_mir(&mut duplicate_root_drop, |main| {
            let block = main.blocks.get_mut(&main.entry).expect("main MIR entry");
            let drop = block
                .instructions
                .iter()
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { .. }
                    )
                })
                .expect("one root Drop")
                .clone();
            block.instructions.push(drop);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_record_unit_mir_route(&duplicate_root_drop).is_err(),
            "the MIR-only validator rejects a duplicate root settlement"
        );
    }

    fn mutate_main_mir(
        program: &mut MirProgram,
        mutate: impl FnOnce(&mut super::super::MirFunction),
    ) {
        let owner = NodeId("function:main".into());
        mutate_owner_mir(program, owner, mutate);
    }

    fn mutate_owner_mir(
        program: &mut MirProgram,
        owner: NodeId,
        mutate: impl FnOnce(&mut super::super::MirFunction),
    ) {
        let mut function = program
            .functions()
            .get(&owner)
            .expect("requested owner MIR")
            .clone();
        mutate(&mut function);
        program.replace_function_for_test_only(function);
    }

    fn insert_main_at_entry(
        program: &mut MirProgram,
        additions: Vec<crate::core::mir::MirInstruction>,
    ) {
        mutate_main_mir(program, |function| {
            function
                .blocks
                .get_mut(&function.entry)
                .expect("main MIR entry block")
                .instructions
                .splice(0..0, additions);
        });
    }

    fn insert_main_after(
        program: &mut MirProgram,
        anchor: &crate::core::mir::MirInstructionId,
        additions: Vec<crate::core::mir::MirInstruction>,
    ) {
        mutate_main_mir(program, |function| {
            let block = function
                .blocks
                .values_mut()
                .find(|block| {
                    block
                        .instructions
                        .iter()
                        .any(|instruction| &instruction.id == anchor)
                })
                .expect("main MIR anchor instruction");
            let index = block
                .instructions
                .iter()
                .position(|instruction| &instruction.id == anchor)
                .expect("main MIR anchor index");
            block.instructions.splice(index + 1..index + 1, additions);
        });
    }

    fn add_main_value(
        program: &mut MirProgram,
        name: &str,
        ty: crate::core::ir::ResolvedTypeId,
    ) -> crate::core::mir::MirValueId {
        let id = crate::core::mir::MirValueId::new(format!("value:zero-miss-extra-{name}"))
            .expect("valid mutation value identity");
        mutate_main_mir(program, |function| {
            assert!(function
                .values
                .insert(
                    id.clone(),
                    crate::core::mir::MirValue { id: id.clone(), ty },
                )
                .is_none());
        });
        id
    }

    fn append_main_instruction(
        program: &mut MirProgram,
        name: &str,
        kind: MirInstructionKind,
    ) -> crate::core::mir::MirInstructionId {
        let id = crate::core::mir::MirInstructionId::new(format!("inst:zero-miss-extra-{name}"))
            .expect("valid mutation instruction identity");
        mutate_main_mir(program, |function| {
            function
                .blocks
                .get_mut(&function.entry)
                .expect("main MIR entry block")
                .instructions
                .push(crate::core::mir::MirInstruction {
                    id: id.clone(),
                    kind,
                });
        });
        id
    }

    fn assert_zero_miss_mutation_rejected(
        checked_program: &CheckedProgram,
        mutated: &MirProgram,
        label: &str,
    ) {
        let island = validate_ordinary_map_owned_any_v2_zero_miss_i32_island(mutated);
        let mir_route = validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(mutated);
        let checked_route =
            validate_ordinary_map_owned_any_v2_zero_miss_i32_route(checked_program, mutated);
        assert!(
            island.is_err(),
            "mutated MIR must fail the whole-program Checker seal or island gate ({label})"
        );
        assert!(
            mir_route.is_err(),
            "MIR-only ZeroMissI32 consumer must reject mutated MIR ({label})"
        );
        assert!(
            checked_route.is_err(),
            "Checker-aware ZeroMissI32 consumer must reject mutated MIR ({label})"
        );
    }

    const ZERO_MISS_I32_SOURCE: &str =
        include_str!("../../../tests/fixtures/mir_ordinary_map_any_owner_v2_zero_miss_i32.mimi");

    #[test]
    fn ordinary_map_owned_any_v2_zero_miss_i32_has_an_independent_exact_route() {
        let checked_program = checked(ZERO_MISS_I32_SOURCE);
        let admission = classify_canonical_mir_route_admission(&checked_program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::ZeroMissI32
        );
        assert_eq!(
            admission.collection,
            ScalarCollectionAdmission::MixedCoverage,
            "the generic scalar-collection scanner sees the final Copy-scalar Bool output beside managed Map values"
        );
        let route = materialize_canonical_mir_route(&checked_program, None)
            .expect("the exact zero/miss Checker profile materializes");
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2ZeroMissI32;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert!(route.materialized_ordinary_map_owned_any_v2_zero_miss_i32_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
        validate_ordinary_map_owned_any_v2_zero_miss_i32_route(&checked_program, &route.program)
            .expect("Checker and MIR observation receipts bind to the exact formula");
        validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&route.program)
            .expect("the independent MIR witness proves both zero payload observations");
        let route_receipt = route
            .ordinary_map_owned_any_v2_zero_miss_i32_route_receipt
            .as_ref()
            .expect("the narrow route has its independent receipt");
        assert_eq!(
            route_receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_ZERO_MISS_I32_PROFILE
        );

        assert!(
            validate_ordinary_map_owned_any_v2_island(&route.program).is_err(),
            "ordinary V2 still rejects the bool Not required by ZeroMiss"
        );
        validate_ordinary_map_owned_any_v2_zero_miss_i32_island(&route.program)
            .expect("the profile-specific gate admits the exact bool Not");

        let mut wrong_checker_return_node = route.program.clone();
        mutate_main_mir(&mut wrong_checker_return_node, |function| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .and_then(|receipt| receipt.zero_miss_i32_observation_receipt.as_mut())
                .expect("the exact Checker ZeroMissI32 observation receipt is embedded")
                .return_node = crate::core::NodeId("expr:forged-tail-return".into());
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&wrong_checker_return_node)
                .is_err(),
            "MIR-only route validation rejects a Checker receipt whose tail return point is absent from its CFG snapshot"
        );

        let formula_node = route
            .program
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .and_then(|receipt| receipt.zero_miss_i32_observation_receipt.as_ref())
            .expect("the exact Checker ZeroMissI32 observation receipt is embedded")
            .formula_node
            .clone();
        assert!(
            route
                .program
                .functions()
                .get(&NodeId("function:main".into()))
                .expect("main MIR")
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_ref()
                .and_then(|receipt| receipt.flow.as_ref())
                .is_some_and(|flow| flow.reachable_blocks.values().any(|block| {
                    block.points.iter().any(|(node, kind)| {
                        node == &formula_node && *kind == crate::core::cfg::CfgPointKind::Expression
                    })
                })),
            "the wrong return-node mutation must use a different real expression node from the Checker CFG snapshot"
        );
        let mut return_at_formula_node = route.program.clone();
        mutate_main_mir(&mut return_at_formula_node, |function| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .and_then(|receipt| receipt.zero_miss_i32_observation_receipt.as_mut())
                .expect("the exact Checker ZeroMissI32 observation receipt is embedded")
                .return_node = formula_node;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&return_at_formula_node)
                .is_err(),
            "MIR-only route validation rejects a return-node forgery to a different real expression in the Checker CFG snapshot"
        );

        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let bool_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::Bool);
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);

        let mut prints_wrong_boolean = route.program.clone();
        let other_boolean = route
            .program
            .ordinary_map_owned_any_v2_found_observation_receipts()
            .expect("two found observations")
            .into_iter()
            .next()
            .expect("hit found observation")
            .found_binding_value;
        mutate_main_mir(&mut prints_wrong_boolean, |function| {
            let print = function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::BuiltinCall {
                            kind: crate::core::mir::types::MirBuiltinKind::PrintlnBool,
                            ..
                        }
                    )
                })
                .expect("one Boolean println instruction");
            let MirInstructionKind::BuiltinCall { arguments, .. } = &mut print.kind else {
                unreachable!()
            };
            assert_eq!(arguments.len(), 1);
            arguments[0] = other_boolean;
        });
        assert_zero_miss_mutation_rejected(
            &checked_program,
            &prints_wrong_boolean,
            "println reads a receipted Boolean other than the formula outcome",
        );

        let mut extra_bool_const = route.program.clone();
        let extra_bool = add_main_value(&mut extra_bool_const, "bool-const", bool_type.clone());
        append_main_instruction(
            &mut extra_bool_const,
            "bool-const",
            MirInstructionKind::Const {
                result: extra_bool,
                literal: crate::core::ir::ResolvedLiteral::Bool(false),
            },
        );
        assert_zero_miss_mutation_rejected(
            &checked_program,
            &extra_bool_const,
            "unreferenced Const(Bool)",
        );

        let mut extra_copy = route.program.clone();
        let found = route
            .program
            .ordinary_map_owned_any_v2_found_observation_receipts()
            .expect("two found observations")
            .into_iter()
            .next()
            .expect("hit found observation")
            .found_binding_value;
        let copy_result = add_main_value(&mut extra_copy, "copy", bool_type.clone());
        append_main_instruction(
            &mut extra_copy,
            "copy",
            MirInstructionKind::Copy {
                result: copy_result,
                source: found,
            },
        );
        assert_zero_miss_mutation_rejected(&checked_program, &extra_copy, "unreferenced Copy");

        let mut extra_move = route.program.clone();
        let hit_payload = route
            .program
            .ordinary_map_owned_any_v2_unpack_result_receipts()
            .expect("two payload receipts")
            .into_iter()
            .next()
            .expect("hit payload receipt")
            .result;
        let move_result = add_main_value(&mut extra_move, "move", i32_type);
        append_main_instruction(
            &mut extra_move,
            "move",
            MirInstructionKind::Move {
                result: move_result,
                source: hit_payload,
            },
        );
        assert_zero_miss_mutation_rejected(&checked_program, &extra_move, "unreferenced Move");

        let mut extra_not = route.program.clone();
        let miss_found = route
            .program
            .ordinary_map_owned_any_v2_found_observation_receipts()
            .expect("two found observations")
            .into_iter()
            .nth(1)
            .expect("miss found observation")
            .found_binding_value;
        let not_result = add_main_value(&mut extra_not, "extra-not", bool_type);
        append_main_instruction(
            &mut extra_not,
            "extra-not",
            MirInstructionKind::Unary {
                result: not_result,
                op: crate::core::ir::ResolvedUnaryOp::Not,
                operand: miss_found,
            },
        );
        assert_zero_miss_mutation_rejected(&checked_program, &extra_not, "extra Boolean Not");

        let mut extra_clone = route.program.clone();
        let set_instruction = route
            .program
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR")
            .blocks
            .values()
            .flat_map(|block| &block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { .. }
                )
            })
            .expect("Set instruction");
        let set_key = match &set_instruction.kind {
            MirInstructionKind::OrdinaryMapOwnedAnyV2Set { key, .. } => key.clone(),
            _ => unreachable!(),
        };
        let clone_result = add_main_value(&mut extra_clone, "clone", string_type.clone());
        let clone_id = crate::core::mir::MirInstructionId::new("inst:zero-miss-extra-clone")
            .expect("valid clone instruction identity");
        let clone_drop_id =
            crate::core::mir::MirInstructionId::new("inst:zero-miss-extra-clone-drop")
                .expect("valid clone Drop instruction identity");
        insert_main_after(
            &mut extra_clone,
            &set_instruction.id,
            vec![
                crate::core::mir::MirInstruction {
                    id: clone_id,
                    kind: MirInstructionKind::Clone {
                        result: clone_result.clone(),
                        source: set_key,
                    },
                },
                crate::core::mir::MirInstruction {
                    id: clone_drop_id,
                    kind: MirInstructionKind::Drop {
                        value: clone_result,
                    },
                },
            ],
        );
        assert_zero_miss_mutation_rejected(&checked_program, &extra_clone, "String Clone");

        let mut extra_add = route.program.clone();
        let left = add_main_value(&mut extra_add, "add-left", string_type.clone());
        let right = add_main_value(&mut extra_add, "add-right", string_type.clone());
        let sum = add_main_value(&mut extra_add, "add-result", string_type.clone());
        append_main_instruction(
            &mut extra_add,
            "add-left-const",
            MirInstructionKind::Const {
                result: left.clone(),
                literal: crate::core::ir::ResolvedLiteral::String("left".into()),
            },
        );
        append_main_instruction(
            &mut extra_add,
            "add-right-const",
            MirInstructionKind::Const {
                result: right.clone(),
                literal: crate::core::ir::ResolvedLiteral::String("right".into()),
            },
        );
        append_main_instruction(
            &mut extra_add,
            "string-add",
            MirInstructionKind::Binary {
                result: sum.clone(),
                op: crate::core::ir::ResolvedBinaryOp::Add,
                left: left.clone(),
                right: right.clone(),
            },
        );
        for (name, value) in [
            ("drop-add-left", left),
            ("drop-add-right", right),
            ("drop-add-result", sum),
        ] {
            append_main_instruction(&mut extra_add, name, MirInstructionKind::Drop { value });
        }
        assert_zero_miss_mutation_rejected(&checked_program, &extra_add, "String Add allocation");

        let same_key =
            ZERO_MISS_I32_SOURCE.replace("map_get(root, \"absent\")", "map_get(root, \"hit\")");
        let crossed_gets = ZERO_MISS_I32_SOURCE.replace(
            "let hit_pair = map_get(root, \"hit\")\n    let miss_pair = map_get(root, \"absent\")",
            "let miss_pair = map_get(root, \"hit\")\n    let hit_pair = map_get(root, \"absent\")",
        );
        let wrong_found_formula = ZERO_MISS_I32_SOURCE.replace(
            "hit_found && hit_payload == 0 && !miss_found",
            "hit_found && hit_payload == 0 && !hit_found",
        );
        let erased_found = ZERO_MISS_I32_SOURCE
            .replace("hit_found && hit_payload == 0", "true && hit_payload == 0");
        let wrong_pair_projection = ZERO_MISS_I32_SOURCE
            .replace("let hit_found = hit_pair.0", "let hit_found = miss_pair.0");
        let crossed_payload_projection = ZERO_MISS_I32_SOURCE.replace(
            "let hit_payload = unpack_i32(hit_pair.1)",
            "let hit_payload = unpack_i32(miss_pair.1)",
        );
        let mutable_key = ZERO_MISS_I32_SOURCE.replace(
            "let miss_pair = map_get(root, \"absent\")",
            "let mut miss_key = \"absent\"\n    let miss_pair = map_get(root, miss_key)",
        );
        let dynamic_key = ZERO_MISS_I32_SOURCE.replace(
            "let miss_pair = map_get(root, \"absent\")",
            "let miss_key = \"absent\" + \"?\"\n    let miss_pair = map_get(root, miss_key)",
        );
        let wrong_set_payload = ZERO_MISS_I32_SOURCE
            .replace("map_set(empty, \"hit\", 0)", "map_set(empty, \"hit\", 1)");
        let extra_operation = ZERO_MISS_I32_SOURCE.replace(
            "    drop(empty)",
            "    let extra_size = map_size(root)\n    drop(empty)",
        );
        for (_, source) in [
            ("same static key", same_key),
            ("crossed Get bindings", crossed_gets),
            ("wrong found flag", wrong_found_formula),
            ("missing found discriminator", erased_found),
            ("found projected from the other pair", wrong_pair_projection),
            (
                "payload projected from the other pair",
                crossed_payload_projection,
            ),
            ("mutable query key", mutable_key),
            ("dynamic query key", dynamic_key),
            ("nonzero Set literal", wrong_set_payload),
            ("extra Map operation", extra_operation),
        ] {
            checked_map_any_unpack_rejection(&source);
        }

        let mut fake_found_receipt = route.program.clone();
        mutate_main_mir(&mut fake_found_receipt, |function| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker owner-v2 CFG receipt")
                .found_observation_receipts[0]
                .projection = NodeId("fake-found-projection".into());
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&fake_found_receipt)
                .is_err(),
            "a forged source found-observation receipt cannot authorize the MIR projection"
        );

        let unpack = route
            .program
            .ordinary_map_owned_any_v2_unpack_result_receipts()
            .expect("two exact unpack result receipts")
            .into_iter()
            .next()
            .expect("one payload receipt");
        let mut wrong_payload_type = route.program.clone();
        mutate_main_mir(&mut wrong_payload_type, |function| {
            function
                .values
                .get_mut(&unpack.result)
                .expect("payload MIR value")
                .ty = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&wrong_payload_type)
                .is_err(),
            "a forged payload TypeDesc cannot replace the canonical i32 result"
        );

        let mut missing_payload_type = route.program.clone();
        mutate_main_mir(&mut missing_payload_type, |function| {
            let set = function
                .ownership
                .checker_ordinary_map_owned_any_v2
                .iter_mut()
                .find(|action| action.kind == crate::core::OrdinaryMapOwnedAnyV2ActionKind::Set)
                .expect("one Checker Set action");
            set.value_type = None;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&missing_payload_type)
                .is_err(),
            "the route cannot proceed without the Checker-selected payload TypeDesc"
        );

        let mut drifted_drop = route.program.clone();
        mutate_main_mir(&mut drifted_drop, |function| {
            let instruction = function
                .blocks
                .values_mut()
                .flat_map(|block| block.instructions.iter_mut())
                .find(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { .. }
                    )
                })
                .expect("one explicit root settlement");
            let MirInstructionKind::OrdinaryMapOwnedAnyV2Drop { root } = &mut instruction.kind
            else {
                unreachable!()
            };
            *root = super::super::MirValueId::new("local:forged-root")
                .expect("valid forged root identity");
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&drifted_drop).is_err(),
            "a root Drop detached from its Checker identity must fail the MIR route"
        );

        let mut missing_pair_drop = route.program.clone();
        let pair_settlement = route
            .program
            .ordinary_map_owned_any_v2_get_any_result_receipts()
            .expect("two GetAny pair receipts")
            .into_iter()
            .next()
            .expect("one GetAny pair receipt")
            .settlement_instruction;
        mutate_main_mir(&mut missing_pair_drop, |function| {
            let block = function
                .blocks
                .values_mut()
                .find(|block| {
                    block
                        .instructions
                        .iter()
                        .any(|instruction| instruction.id == pair_settlement)
                })
                .expect("pair settlement block");
            let index = block
                .instructions
                .iter()
                .position(|instruction| instruction.id == pair_settlement)
                .expect("pair settlement instruction");
            block.instructions.remove(index);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&missing_pair_drop).is_err(),
            "both GetAny pair owners must be explicitly settled"
        );

        let mut crossed_pair_settlement = route.program.clone();
        mutate_main_mir(&mut crossed_pair_settlement, |function| {
            let unpack_receipts = &mut function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker owner-v2 CFG receipt")
                .unpack_receipts;
            assert_eq!(unpack_receipts.len(), 2);
            let first = unpack_receipts[0].settlement_point.clone();
            unpack_receipts[0].settlement_point = unpack_receipts[1].settlement_point.clone();
            unpack_receipts[1].settlement_point = first;
        });
        let crossed_settlement_error =
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&crossed_pair_settlement)
                .expect_err("each pair must retain its own exact Drop settlement");
        assert!(
            crossed_settlement_error.contains("does not join one exact GetAny pair/drop receipt")
                || (crossed_settlement_error.contains("GetAny receipt derivation failed")
                    && crossed_settlement_error.contains("non-observation/non-drop use")),
            "unexpected crossed-settlement rejection: {crossed_settlement_error}"
        );

        let mut extra_root_drop = route.program.clone();
        mutate_main_mir(&mut extra_root_drop, |function| {
            let root = function
                .blocks
                .values()
                .flat_map(|block| &block.instructions)
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { result, .. } => {
                        Some(result.clone())
                    }
                    _ => None,
                })
                .expect("persistent Set root");
            let block = function
                .blocks
                .get_mut(&function.entry)
                .expect("main MIR entry block");
            block.instructions.push(crate::core::mir::MirInstruction {
                id: crate::core::mir::MirInstructionId::new("inst:forged-raw-root-drop")
                    .expect("valid forged Drop instruction identity"),
                kind: MirInstructionKind::Drop { value: root },
            });
        });
        assert_zero_miss_mutation_rejected(
            &checked_program,
            &extra_root_drop,
            "generic Drop of the persistent Set root",
        );

        let mut extra_new_root_drop = route.program.clone();
        mutate_main_mir(&mut extra_new_root_drop, |function| {
            let root = function
                .blocks
                .values()
                .flat_map(|block| &block.instructions)
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2New { result } => Some(result.clone()),
                    _ => None,
                })
                .expect("initial New root");
            let block = function
                .blocks
                .get_mut(&function.entry)
                .expect("main MIR entry block");
            block.instructions.push(crate::core::mir::MirInstruction {
                id: crate::core::mir::MirInstructionId::new("inst:forged-raw-new-root-drop")
                    .expect("valid forged Drop instruction identity"),
                kind: MirInstructionKind::Drop { value: root },
            });
        });
        assert_zero_miss_mutation_rejected(
            &checked_program,
            &extra_new_root_drop,
            "generic Drop of the initial New root",
        );

        let mut extra_pair_drop = route.program.clone();
        let pair_receipt = route
            .program
            .ordinary_map_owned_any_v2_get_any_result_receipts()
            .expect("two GetAny pair receipts")
            .into_iter()
            .next()
            .expect("one GetAny pair receipt");
        mutate_main_mir(&mut extra_pair_drop, |function| {
            let block_id = function
                .blocks
                .iter()
                .find_map(|(block_id, block)| {
                    block
                        .instructions
                        .iter()
                        .any(|instruction| instruction.id == pair_receipt.settlement_instruction)
                        .then_some(block_id.clone())
                })
                .expect("one receipted pair Drop");
            function
                .blocks
                .get_mut(&block_id)
                .expect("pair settlement block")
                .instructions
                .push(crate::core::mir::MirInstruction {
                    id: crate::core::mir::MirInstructionId::new("inst:forged-extra-pair-drop")
                        .expect("valid extra Drop instruction identity"),
                    kind: MirInstructionKind::Drop {
                        value: pair_receipt.binding.clone(),
                    },
                });
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&extra_pair_drop).is_err(),
            "an extra pair Drop cannot enter the exact temporary/pair Drop census"
        );

        let mut extra_key_drop = route.program.clone();
        mutate_main_mir(&mut extra_key_drop, |function| {
            let block = function
                .blocks
                .values_mut()
                .find(|block| {
                    block.instructions.iter().any(|instruction| {
                        matches!(
                            &instruction.kind,
                            MirInstructionKind::OrdinaryMapOwnedAnyV2Set { .. }
                        )
                    })
                })
                .expect("Set operation block");
            let set_key = block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    MirInstructionKind::OrdinaryMapOwnedAnyV2Set { key, .. } => Some(key.clone()),
                    _ => None,
                })
                .expect("Set key temporary");
            let key_drop_index = block
                .instructions
                .iter()
                .position(|instruction| matches!(&instruction.kind, MirInstructionKind::Drop { value } if value == &set_key))
                .expect("Set key temporary Drop");
            block.instructions.insert(
                key_drop_index + 1,
                crate::core::mir::MirInstruction {
                    id: crate::core::mir::MirInstructionId::new("inst:forged-extra-unrelated-drop")
                        .expect("valid extra Drop identity"),
                    kind: MirInstructionKind::Drop { value: set_key },
                },
            );
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&extra_key_drop).is_err(),
            "an unrelated or duplicated generic Drop cannot enter the exact Drop census"
        );

        let mut self_call = route.program.clone();
        mutate_main_mir(&mut self_call, |function| {
            let result = super::super::MirValueId::new("value:forged-zero-miss-self-call")
                .expect("valid call result identity");
            function.values.insert(
                result.clone(),
                crate::core::mir::MirValue {
                    id: result.clone(),
                    ty: function.result.clone(),
                },
            );
            function
                .blocks
                .get_mut(&function.entry)
                .expect("main MIR entry block")
                .instructions
                .push(crate::core::mir::MirInstruction {
                    id: crate::core::mir::MirInstructionId::new("inst:forged-zero-miss-self-call")
                        .expect("valid self-call instruction identity"),
                    kind: MirInstructionKind::Call {
                        result: Some(result),
                        callee: crate::core::ir::ResolvedCallee::Function(NodeId(
                            "function:main".into(),
                        )),
                        type_arguments: Vec::new(),
                        arguments: Vec::new(),
                        effect_receipts: Vec::new(),
                        variant_call_contract: None,
                    },
                });
        });
        assert!(
            validate_ordinary_map_owned_any_v2_zero_miss_i32_mir_route(&self_call).is_err(),
            "an injected self-call cannot use the exact output-only route"
        );
        assert!(validate_ordinary_map_owned_any_v2_island(&self_call).is_err());
        assert!(validate_ordinary_map_owned_any_v2_zero_miss_i32_route(
            &checked_program,
            &self_call
        )
        .is_err());
    }

    const COMPUTED_KEY_GET_SOURCE: &str = r#"
func main() -> i32 {
    let left = "runtime"
    let right = "-key"
    let key = left + right
    let empty = map_new()
    let updated = map_set(empty, key, 42)
    let pair = map_get(updated, key)
    drop(empty)
    drop(updated)
    let value = unpack_i32(pair.1)
    drop(pair)
    value
}
"#;

    const COMPUTED_KEY_STRING_GET_SOURCE: &str = include_str!(
        "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_computed_key_get_string.mimi"
    );

    const DIRECT_PRINT_SOURCE: &str = r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 42)
    let pair = map_get(root, "answer")
    drop(empty)
    drop(root)
    println(pair.1)
    drop(pair)
    0
}
"#;

    #[test]
    fn scalar_ffi_has_no_composition_route_with_narrow_map_any_v2_profiles() {
        let computed_key_source = format!(
            r#"
extern "C" {{ func scalar_probe(value: i32) -> i32; }}
func unused_scalar_ffi_helper() -> i32 {{ scalar_probe(0) }}
{COMPUTED_KEY_GET_SOURCE}
"#
        );
        let checked_get_source = r#"
extern "C" { func scalar_probe(value: i32) -> i32; }
func unused_scalar_ffi_helper() -> i32 { scalar_probe(0) }
func main() -> bool {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let pair = map_get(root, "answer")
    drop(empty)
    drop(root)
    let found = pair.0
    let payload = unpack_i32(pair.1)
    drop(pair)
    found
}
"#;
        let cases = [
            (
                "ComputedKeyGet",
                computed_key_source.as_str(),
                OrdinaryMapOwnedAnyV2Admission::ComputedKeyGet,
                CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2ComputedKeyGet,
            ),
            (
                "CheckedGet",
                checked_get_source,
                OrdinaryMapOwnedAnyV2Admission::CheckedGet,
                CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2CheckedGet,
            ),
        ];

        for (label, source, expected_admission, expected_profile) in cases {
            let checked = checked(source);
            let admission = classify_canonical_mir_route_admission(&checked);
            assert!(
                admission.scalar_ffi,
                "{label} fixture must retain scalar FFI"
            );
            assert_eq!(
                admission.ordinary_map_owned_any_v2, expected_admission,
                "{label} fixture must retain its exact narrow Map/Any admission"
            );
            assert!(
                !ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY,
                "narrow composition rejection must not open global V2 readiness"
            );

            let failure = scalar_ffi_map_owner_composition_failure(admission)
                .expect("the shared composition gate must reject a narrow owner-v2 profile");
            match failure {
                CanonicalMirRouteMaterializationError::Complete {
                    profile,
                    stage,
                    message,
                } => {
                    assert_eq!(profile, expected_profile, "{label} diagnostic profile");
                    assert_eq!(stage, CanonicalMirRouteFailureStage::Coverage);
                    assert!(message.contains("cannot be combined"), "{label}: {message}");
                    assert!(message.contains("scalar FFI"), "{label}: {message}");
                }
                other => panic!("{label} composition must be a Complete rejection: {other:?}"),
            }

            let materialization_error = materialize_canonical_mir_route(&checked, None)
                .expect_err("public route materialization must reject Map-owner plus scalar FFI");
            match materialization_error {
                CanonicalMirRouteMaterializationError::Complete {
                    profile,
                    stage,
                    message,
                } => {
                    assert_eq!(profile, expected_profile, "{label} materializer profile");
                    assert_eq!(stage, CanonicalMirRouteFailureStage::Coverage);
                    assert!(message.contains("cannot be combined"), "{label}: {message}");
                    assert!(message.contains("scalar FFI"), "{label}: {message}");
                }
                other => panic!("{label} materializer must fail closed: {other:?}"),
            }
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_direct_print_has_its_own_receipted_route() {
        let checked_program = checked(DIRECT_PRINT_SOURCE);
        let admission = classify_canonical_mir_route_admission(&checked_program);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::DirectPrint
        );
        assert!(CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2DirectPrint.is_admitted(admission));
        assert!(!CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2.is_admitted(admission));
        assert_eq!(
            CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2DirectPrint.as_str(),
            "map-any-owner-v2-direct-print-v1"
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let route = materialize_canonical_mir_route(&checked_program, None)
            .expect("the exact direct-print receipt materializes as its narrow profile");
        assert!(route.materialized_ordinary_map_owned_any_v2_direct_print_candidate);
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2DirectPrint.is_materialized(&route));
        assert!(!CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2.is_materialized(&route));
        let receipt = route
            .ordinary_map_owned_any_v2_direct_print_route_receipt
            .as_ref()
            .expect("the direct-print route identity has its own MIR receipt");
        assert_eq!(
            receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_DIRECT_PRINT_PROFILE
        );
        validate_ordinary_map_owned_any_v2_direct_print_mir_route(&route.program)
            .expect("the Checker selection, direct print, and pair Drop are joined");
        validate_ordinary_map_owned_any_v2_island(&route.program)
            .expect("the full materialized graph remains in the V2 island");
        assert!(validate_ordinary_map_owned_any_v2_checked_get_route(&route.program).is_err());

        let repeated_print = checked(&DIRECT_PRINT_SOURCE.replace(
            "    println(pair.1)\n",
            "    println(pair.1)\n    println(pair.1)\n",
        ));
        assert_ne!(
            classify_ordinary_map_owned_any_v2_admission(&repeated_print),
            OrdinaryMapOwnedAnyV2Admission::DirectPrint,
            "a repeated observation is outside the one-print receipt"
        );
        assert!(
            matches!(
                materialize_canonical_mir_route(&repeated_print, None),
                Err(CanonicalMirRouteMaterializationError::Complete { .. })
            ),
            "a partial or repeated V2 print candidate cannot fall back to compatibility"
        );

        let escaped_payload = checked(&DIRECT_PRINT_SOURCE.replace(
            "    println(pair.1)\n",
            "    let payload = pair.1\n    println(payload)\n",
        ));
        assert_ne!(
            classify_ordinary_map_owned_any_v2_admission(&escaped_payload),
            OrdinaryMapOwnedAnyV2Admission::DirectPrint,
            "the payload projection must be printed directly, without an alias"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_direct_print_admits_only_one_post_print_same_root_size() {
        let same_root_size = DIRECT_PRINT_SOURCE.replace(
            "    drop(empty)\n    drop(root)\n    println(pair.1)\n    drop(pair)\n    0",
            "    drop(empty)\n    println(pair.1)\n    let size = map_size(root)\n    drop(pair)\n    drop(root)\n    size",
        );
        let program = checked(&same_root_size);
        assert_eq!(
            classify_ordinary_map_owned_any_v2_admission(&program),
            OrdinaryMapOwnedAnyV2Admission::DirectPrint,
            "the one direct size read is admitted only for the updated root after println"
        );
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("main resource analysis");
        let size_actions = analysis
            .ordinary_map_owned_any_v2_actions
            .iter()
            .filter(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::Size)
            .collect::<Vec<_>>();
        let size_attempts = analysis
            .ordinary_map_owned_any_v2_operation_attempts
            .iter()
            .filter(|attempt| attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Size)
            .collect::<Vec<_>>();
        let [size_action] = size_actions.as_slice() else {
            panic!("the source size observation has one unique Checker action");
        };
        let [size_attempt] = size_attempts.as_slice() else {
            panic!("the source size observation has one unique Checker attempt");
        };
        let set_action = analysis
            .ordinary_map_owned_any_v2_actions
            .iter()
            .find(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::Set)
            .expect("persistent Set action");
        assert_eq!(size_action.local, set_action.local);
        assert_eq!(size_action.root, set_action.root);
        assert_eq!(size_attempt.point, size_action.point);
        assert_eq!(
            size_attempt.receiver_local.as_ref(),
            Some(&set_action.local)
        );
        assert_eq!(size_attempt.arguments.len(), 1);

        for (label, source) in [
            (
                "new root",
                same_root_size.replace(
                    "    drop(empty)\n    println(pair.1)\n    let size = map_size(root)\n",
                    "    println(pair.1)\n    let size = map_size(empty)\n    drop(empty)\n",
                ),
            ),
            (
                "repeated size",
                same_root_size
                    .replace(
                        "    let size = map_size(root)\n",
                        "    let first_size = map_size(root)\n    let size = map_size(root)\n",
                    )
                    .replace("    size\n", "    first_size + size\n"),
            ),
            (
                "size before print",
                same_root_size.replace(
                    "    println(pair.1)\n    let size = map_size(root)\n",
                    "    let size = map_size(root)\n    println(pair.1)\n",
                ),
            ),
            (
                "extra Map operation",
                same_root_size.replace(
                    "    let size = map_size(root)\n",
                    "    let size = map_size(root)\n    let present = has_key(root, \"answer\")\n",
                ),
            ),
        ] {
            let rejected = checked(&source);
            assert_ne!(
                classify_ordinary_map_owned_any_v2_admission(&rejected),
                OrdinaryMapOwnedAnyV2Admission::DirectPrint,
                "DirectPrint rejects a {label} size observation"
            );
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_direct_print_accounts_for_set_effect_without_opening_shared_effects(
    ) {
        for (label, source) in [
            ("i32 hit", DIRECT_PRINT_SOURCE.to_owned()),
            (
                "negative i32 hit",
                DIRECT_PRINT_SOURCE
                    .replace(
                        "    let empty = map_new()",
                        "    let negative: i32 = -137\n    let empty = map_new()",
                    )
                    .replace("\"answer\", 42", "\"answer\", negative"),
            ),
            (
                "String hit",
                DIRECT_PRINT_SOURCE.replace("\"answer\", 42", "\"answer\", \"owned text\""),
            ),
            (
                "String hit with NUL and multibyte text",
                DIRECT_PRINT_SOURCE.replace("\"answer\", 42", "\"answer\", \"owned\\0🧪 值\""),
            ),
            (
                "String payload with canonical i32 miss",
                DIRECT_PRINT_SOURCE
                    .replace("\"answer\", 42", "\"answer\", \"present payload\"")
                    .replace("map_get(root, \"answer\")", "map_get(root, \"missing\")"),
            ),
        ] {
            let checked_program = checked(&source);
            let main = checked_program
                .callable(&NodeId("function:main".into()))
                .expect("main callable");
            assert!(
                !super::super::verification::callable_effect_model_is_direct_stdout_only(
                    main,
                    &checked_program
                ),
                "the scalar stdout audit must continue rejecting the persistent Set effect"
            );
            assert_eq!(
                classify_ordinary_map_owned_any_v2_admission(&checked_program),
                OrdinaryMapOwnedAnyV2Admission::DirectPrint,
                "only the exact Set and print receipts account for this shared.modify bucket ({label})"
            );
            let catalog = super::super::types::MirTypeCatalog::from_checked_program(
                &checked_program,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "the source-only DirectPrint predicate selects one V2 TypeCatalog identity ({label}): {error:?}"
                )
            });
            catalog
                .validate_glue(
                    &super::super::types::ordinary_map_owned_any_v2_type_id(),
                    super::super::types::MirGlueOperation::Drop,
                )
                .expect("the selected V2 owner retains its exact Drop contract");
            let route = materialize_canonical_mir_route(&checked_program, None).expect(
                "the narrow DirectPrint route materializes independently of broad readiness",
            );
            validate_ordinary_map_owned_any_v2_direct_print_island(&route.program)
                .expect("the receipted direct print and its selected TypeCatalog agree");
            assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        }

        for extra in ["shared retained = 42", "eprintln(\"unrelated output\")"] {
            let source = DIRECT_PRINT_SOURCE.replace(
                "    let empty = map_new()",
                &format!("    {extra}\n    let empty = map_new()"),
            );
            let checked_program = checked(&source);
            assert_ne!(
                classify_ordinary_map_owned_any_v2_admission(&checked_program),
                OrdinaryMapOwnedAnyV2Admission::DirectPrint,
                "an unrelated effect cannot borrow Set/stdout authority: {extra}"
            );
            assert!(
                materialize_canonical_mir_route(&checked_program, None).is_err(),
                "the non-DirectPrint V2 candidate must remain fail-closed: {extra}"
            );
        }

        let mut explicit_flow_with_unknown_call = String::from(
            r#"
extern "C" { func foreign_i32(value: i32) -> i32; }
flow Worker {
    state Ready { value: i32 }
    transition tick(Ready) -> Ready {
        return Ready { value: foreign_i32(self.value) }
    }
}
"#,
        );
        explicit_flow_with_unknown_call.push_str(DIRECT_PRINT_SOURCE);
        let explicit_flow_program = checked(&explicit_flow_with_unknown_call);
        let explicit_flow_call = explicit_flow_program
            .call_sites_sorted()
            .into_iter()
            .find(|site| site.callee == "foreign_i32")
            .expect("the explicit user Flow retains its extern call site");
        assert_ne!(explicit_flow_call.owner, "function:main");
        assert!(matches!(
            &explicit_flow_call.origin,
            crate::core::Origin::User(_)
        ));
        assert!(explicit_flow_call
            .effects
            .iter()
            .any(|effect| effect == "unknown"));
        assert_ne!(
            classify_ordinary_map_owned_any_v2_admission(&explicit_flow_program),
            OrdinaryMapOwnedAnyV2Admission::DirectPrint,
            "an explicit user Flow's unknown call cannot use the synthetic Main peer_fault exemption"
        );
        assert!(materialize_canonical_mir_route(&explicit_flow_program, None).is_err());
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

