    #[test]
    fn map_root_producer_caller_incomplete_source_shapes_never_reach_complete_coverage() {
        let fixture = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_map_root_producer_caller.mimi"
        );

        let missing_drop = fixture.replace("    drop(received_root)\n", "");
        assert_ne!(missing_drop, fixture);
        let checked_missing_drop = checked(&missing_drop);
        assert_eq!(
            classify_canonical_mir_route_admission(&checked_missing_drop).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "a Map-root returned across the call boundary cannot borrow broad CompleteCoverage"
        );
        assert!(matches!(
            materialize_canonical_mir_route(&checked_missing_drop, None),
            Err(CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                ..
            })
        ));

        let second_caller = format!(
            "{}\nfunc second_caller() -> i32 {{\n    let root = make_root()\n    let count = map_size(root)\n    drop(root)\n    count\n}}\n",
            fixture
        );
        let checked_second_caller = checked(&second_caller);
        assert_eq!(
            classify_canonical_mir_route_admission(&checked_second_caller)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "a second direct caller invalidates the unique-caller bridge"
        );
        assert!(matches!(
            materialize_canonical_mir_route(&checked_second_caller, None),
            Err(CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                ..
            })
        ));

        let missing_payload_drop = fixture.replace("    drop(payload)\n", "");
        assert_ne!(missing_payload_drop, fixture);
        let checked_missing_payload_drop = checked(&missing_payload_drop);
        assert_eq!(
            classify_canonical_mir_route_admission(&checked_missing_payload_drop)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "the payload must be settled before the final root is returned"
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn map_root_producer_caller_mir_route_rejects_missing_and_forged_receipts() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_map_root_producer_caller.mimi"
        );
        let checked = checked(source);
        let route = materialize_canonical_mir_route(&checked, None)
            .expect("the exact route materializes before adversarial mutations");
        let bridges = route
            .program
            .ordinary_map_owned_any_v2_map_root_producer_caller_receipts()
            .expect("initial bridge rederives");
        let [bridge] = bridges.as_slice() else {
            panic!("one root bridge")
        };

        let mut missing_checker_caller = route.program.clone();
        let mut producer = missing_checker_caller
            .functions()
            .get(&bridge.producer_owner)
            .expect("producer MIR")
            .clone();
        producer
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker CFG receipt")
            .map_root_producer_caller_receipt = None;
        missing_checker_caller.replace_function_for_test_only(producer);
        assert!(missing_checker_caller
            .ordinary_map_owned_any_v2_map_root_producer_caller_receipts()
            .expect("an incomplete private source pair yields no receipt")
            .is_empty());
        assert!(
            validate_ordinary_map_owned_any_v2_map_root_producer_caller_mir_route(
                &missing_checker_caller
            )
            .is_err()
        );

        let mut forged_checker_target = route.program.clone();
        let mut producer = forged_checker_target
            .functions()
            .get(&bridge.producer_owner)
            .expect("producer MIR")
            .clone();
        producer
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker CFG receipt")
            .map_root_producer_caller_receipt
            .as_mut()
            .expect("Checker caller receipt")
            .call_target = NodeId("function:forged_target".into());
        forged_checker_target.replace_function_for_test_only(producer);
        assert!(forged_checker_target
            .ordinary_map_owned_any_v2_map_root_producer_caller_receipts()
            .is_err());

        let mut missing_mir_drop = route.program.clone();
        let mut caller = missing_mir_drop
            .functions()
            .get(&bridge.caller_owner)
            .expect("caller MIR")
            .clone();
        for block in caller.blocks.values_mut() {
            block
                .instructions
                .retain(|instruction| instruction.id != bridge.caller_root_drop_instruction);
        }
        missing_mir_drop.replace_function_for_test_only(caller);
        assert!(missing_mir_drop
            .ordinary_map_owned_any_v2_map_root_producer_caller_receipts()
            .is_err());
        assert!(
            validate_ordinary_map_owned_any_v2_map_root_producer_caller_route(
                &checked,
                &missing_mir_drop
            )
            .is_err()
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn string_values_producer_caller_source_intent_without_unique_receipt_fails_closed() {
        let fixture = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_values_producer_caller.mimi"
        );
        let source = fixture.replacen(
            "let count = snapshot.len()\n    drop(snapshot)\n    count",
            "let count = snapshot.len()\n    let duplicate = snapshot.len()\n    drop(snapshot)\n    count + duplicate",
            1,
        );
        assert_ne!(
            source, fixture,
            "the fixture caller has one len observation"
        );
        let program = checked(&source);
        let producer = program
            .resource_analysis(&NodeId("function:snapshot_values".into()))
            .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
            .expect("the source still carries its producer CFG receipt");
        assert!(producer.values_producer_return_receipt.is_some());
        assert!(
            producer.values_producer_caller_receipt.is_none(),
            "a second List len observation withholds the narrow caller receipt"
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "the typed String Set -> Values -> direct caller intent stays a candidate without its unique receipt"
        );
        assert!(matches!(
            materialize_canonical_mir_route(&program, None),
            Err(CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                ..
            })
        ));
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let ordinary_string_set = checked(
            r#"
func main() -> i32 {
    let payload = "value"
    let empty = map_new()
    let root = map_set(empty, "key", payload)
    drop(empty)
    drop(root)
    drop(payload)
    0
}
"#,
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&ordinary_string_set).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::OutsideProfile,
            "ordinary String Map writes remain outside the Values producer-caller candidate"
        );
    }

    #[test]
    fn values_producer_caller_rejects_forged_call_drop_and_indexed_unpack() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_values_producer_caller.mimi"
        );
        let program = checked(source);
        let route = materialize_canonical_mir_route(&program, None)
            .expect("the exact producer-return/direct-caller V1 profile materializes");
        let bridge = route
            .program
            .ordinary_map_owned_any_v2_values_producer_caller_receipts()
            .expect("bridge")
            .into_iter()
            .next()
            .expect("one bridge");

        let mut forged_call = route.program.clone();
        let mut caller = forged_call
            .functions()
            .get(&bridge.caller_owner)
            .expect("caller function")
            .clone();
        let mut changed_call = false;
        for block in caller.blocks.values_mut() {
            for instruction in &mut block.instructions {
                if instruction.id == bridge.call_instruction {
                    let MirInstructionKind::Call { callee, .. } = &mut instruction.kind else {
                        panic!("the receipted direct call uses the Call opcode")
                    };
                    *callee = crate::core::ir::ResolvedCallee::Function(NodeId(
                        "function:forged_target".into(),
                    ));
                    changed_call = true;
                }
            }
        }
        assert!(changed_call, "the exact caller Call identity is present");
        forged_call.replace_function_for_test_only(caller);
        assert!(
            forged_call
                .ordinary_map_owned_any_v2_values_producer_caller_receipts()
                .is_err(),
            "a substituted Call target must not inherit the producer receipt"
        );

        let mut forged_drop = route.program.clone();
        let mut caller = forged_drop
            .functions()
            .get(&bridge.caller_owner)
            .expect("caller function")
            .clone();
        let mut changed_drop = false;
        for block in caller.blocks.values_mut() {
            for instruction in &mut block.instructions {
                if instruction.id == bridge.owner_drop_instruction {
                    let MirInstructionKind::Drop { value } = &mut instruction.kind else {
                        panic!("the receipted owner settlement uses Drop")
                    };
                    *value = crate::core::mir::MirValueId::new("local:forged_values_owner")
                        .expect("test value id");
                    changed_drop = true;
                }
            }
        }
        assert!(changed_drop, "the exact caller Drop identity is present");
        forged_drop.replace_function_for_test_only(caller);
        assert!(
            forged_drop
                .ordinary_map_owned_any_v2_values_producer_caller_receipts()
                .is_err(),
            "the whole Drop must settle the exact caller Call result owner"
        );

        let mut forged_extra_owner_use = route.program.clone();
        let mut caller = forged_extra_owner_use
            .functions()
            .get(&bridge.caller_owner)
            .expect("caller function")
            .clone();
        let block = caller
            .blocks
            .get_mut(&caller.entry.clone())
            .expect("caller entry block");
        block.instructions.push(crate::core::mir::MirInstruction {
            id: crate::core::mir::MirInstructionId::new("inst:forged:extra_values_owner_use")
                .expect("test instruction id"),
            kind: MirInstructionKind::Drop {
                value: bridge.caller_binding.clone(),
            },
        });
        forged_extra_owner_use.replace_function_for_test_only(caller);
        assert!(
            forged_extra_owner_use
                .ordinary_map_owned_any_v2_values_producer_caller_receipts()
                .is_err(),
            "the caller owner cannot have an unreceipted extra use"
        );

        let mut forged_unpack = route.program.clone();
        let mut caller = forged_unpack
            .functions()
            .get(&bridge.caller_owner)
            .expect("caller function")
            .clone();
        let block = caller
            .blocks
            .get_mut(&caller.entry.clone())
            .expect("caller entry block");
        block.instructions.push(crate::core::mir::MirInstruction {
            id: crate::core::mir::MirInstructionId::new("inst:forged:values_unpack")
                .expect("test instruction id"),
            kind: MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack {
                result: crate::core::mir::MirValueId::new("expr:forged_unpack")
                    .expect("test result id"),
                values: bridge.caller_binding.clone(),
                index: crate::core::mir::MirValueId::new("const:forged_index")
                    .expect("test index id"),
                projection: NodeId("node:forged_unpack_projection".into()),
            },
        });
        forged_unpack.replace_function_for_test_only(caller);
        let error = forged_unpack
            .ordinary_map_owned_any_v2_values_producer_caller_receipts()
            .expect_err("V1 must reject even a forged cross-function indexed unpack");
        assert!(
            error.contains("rejects indexed Values unpack")
                || error
                    .contains("Len/owner result bindings have an extra use or are out of order"),
            "an indexed unpack must fail either its dedicated census or the earlier exact owner-use proof: {error}"
        );
    }

