    #[test]
    fn ordinary_map_owned_any_v2_route_rejects_erased_label_source_use_commitment() {
        let (checked, mut functions, catalog) =
            super::super::test_support::ordinary_map_values_label_erased_alias_fixture();
        let owner = NodeId("function:main".into());
        let source = &checked
            .resource_analysis(&owner)
            .expect("Checker owner analysis")
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("Checker V2 receipt")
            .values_unpack_receipts[0];
        assert!(
            source
                .result_owner_whole_drop_unproved_uses
                .as_ref()
                .is_some_and(|uses| !uses.is_empty()),
            "the actual source contains an alias Load"
        );

        // Model an additional faulty transfer of source proof into MIR: the
        // independently checked nonempty census is replaced by Some(empty).
        // Internal MIR derivation can validate that forged claim, but route
        // admission must compare it with the original CheckedProgram.
        functions
            .get_mut(&owner)
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("MIR V2 receipt")
            .values_unpack_receipts[0]
            .result_owner_whole_drop_unproved_uses = Some(Default::default());
        let canonical = MirProgram::with_type_catalog(functions, catalog)
            .expect("test-only resealed MIR with the forged source proof is internally consistent");
        let receipts = canonical
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("derived MIR receipts");
        assert_eq!(receipts.len(), 1);
        assert_eq!(
            receipts[0].result_owner_whole_drop_unproved_uses,
            Some(Default::default())
        );
        let error = validate_ordinary_map_owned_any_v2_values_unpack_receipts(&checked, &canonical)
            .expect_err("route admission must retain the original Checker source-use census");
        assert!(
            error.contains("Core route receipt disagrees with Checker evidence"),
            "{error}"
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_index_unpack_is_a_complete_candidate() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_values_unpack.mimi"
        )
        .replace("snapshot[2] as Label", "snapshot[-1] as Label");
        let program = checked(&source);
        assert_eq!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::CompleteCoverage
        );

        let canonical = MirProgram::from_checked_program(&program)
            .expect("canonical MIR validates the direct indexed Values unpack receipts");
        let receipts = canonical
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("exact Values unpack receipt derivation")
            .into_iter()
            .collect::<Vec<_>>();
        assert_eq!(receipts.len(), 4);
        for receipt in &receipts {
            receipt
                .validate_against_program(&canonical)
                .expect("the Checker, index, selection, binding, and Drop identities agree");
            assert_eq!(receipt.conversion_to, receipt.result_type);
        }
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        assert_eq!(
            receipts
                .iter()
                .filter(|receipt| receipt.result_type == i32_type)
                .count(),
            2,
            "literal and dynamic integer indexes retain distinct receipts"
        );
        assert_eq!(
            receipts
                .iter()
                .filter(|receipt| receipt.result_type == string_type)
                .count(),
            1,
            "the String result receipt proves compiler-owned tail cleanup"
        );
        assert_eq!(
            receipts
                .iter()
                .filter(
                    |receipt| receipt.result_type != i32_type && receipt.result_type != string_type
                )
                .count(),
            1,
            "the Label result receipt proves explicit whole-value Drop"
        );
        assert!(
            receipts.iter().all(|receipt| {
                receipt.values_binding_local == receipts[0].values_binding_local
            }),
            "all indexed reads are tied to the same directly bound snapshot"
        );

        let mut forged = receipts[0].clone();
        forged.result_binding_local =
            crate::core::ir::ResolvedLocalId(NodeId("forged-result".into()));
        assert!(forged.validate_against_program(&canonical).is_err());

        let diagnostic = materialize_ordinary_map_owned_any_v2_for_verifier_diagnostics(
            &program, None,
        )
        .expect("the verifier diagnostic path can materialize the receipted Values candidate");
        assert_eq!(
            diagnostic.admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::CompleteCoverage
        );
        assert!(diagnostic.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let error = materialize_canonical_mir_route(&program, None)
            .expect_err("CompleteCoverage must remain behind the production-readiness gate");
        assert!(error
            .to_string()
            .contains("production-readiness gate is closed"));
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_static_oob_without_selected_target_is_materializable() {
        let program = checked(
            r#"
func main() -> i32 {
    let text = "only selected String payload"
    let empty = map_new()
    let root = map_set(empty, "string", text)
    let snapshot = values(root)
    let rejected = snapshot[1] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    drop(text)
    0
}
"#,
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::CompleteCoverage,
            "an exact Checker Values OOB receipt is candidate intent even when its target type is absent from every Set"
        );

        let canonical = MirProgram::from_checked_program(&program)
            .expect("canonical MIR materializes the receipt-bound static OOB Values operation");
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let selection = canonical
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("Map payload selection receipt")
            .expect("String Set contributes the only selected payload type");
        assert_eq!(selection.selected_types.len(), 1);
        assert_eq!(selection.selected_types[0].type_id, string_type);
        assert!(selection
            .selected_types
            .iter()
            .all(|selected| selected.type_id != i32_type));

        let receipts = canonical
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("MIR independently reconstructs the static OOB receipt");
        let [receipt] = receipts.as_slice() else {
            panic!("one static OOB Values unpack receipt");
        };
        assert_eq!(receipt.result_type, i32_type);
        assert_eq!(
            receipt.index_disposition,
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::AlwaysOutOfBounds {
                raw_index: 1,
                snapshot_len: 1,
            }
        );
        let checker_receipt = &canonical
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker Values receipt")
            .values_unpack_receipts[0];
        assert!(checker_receipt.payload_selection.is_empty());
        receipt
            .validate_against_program(&canonical)
            .expect("the receipt binds the exact OOB index without inventing a payload selection");

        let diagnostic =
            materialize_ordinary_map_owned_any_v2_for_verifier_diagnostics(&program, None)
                .expect("verifier diagnostics can inspect the exact static OOB candidate");
        assert!(diagnostic.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn values_local_index_i32_is_independently_admitted_and_mir_sealed() {
        let checked_program = checked(VALUES_LOCAL_INDEX_I32_FIXTURE);
        assert_eq!(
            classify_canonical_mir_route_admission(&checked_program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::ValuesLocalIndexI32
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let canonical = MirProgram::from_checked_program(&checked_program)
            .expect("canonical MIR for immutable local zero-index Values unpack");
        let witnesses = canonical
            .ordinary_map_owned_any_v2_values_local_index_i32_receipts()
            .expect("Checker local-index receipt joins the MIR producer and unpack");
        assert_eq!(witnesses.len(), 1);
        let witness = &witnesses[0];
        witness
            .validate_against_program(&canonical)
            .expect("Const(0), index binding Move, and unpack operand are exact");
        assert_eq!(witness.literal_value, 0);
        assert_eq!(
            witness.index_type,
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
        );
        assert_eq!(witness.unpack.index, witness.index_local);
        assert_eq!(witness.unpack.index_expression, witness.index_expression);
        assert_eq!(
            witness.profile,
            ORDINARY_MAP_OWNED_ANY_V2_VALUES_LOCAL_INDEX_I32_PROFILE
        );
        let route = materialize_canonical_mir_route(&checked_program, None).expect(
            "the independent narrow profile materializes while broad readiness stays closed",
        );
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2ValuesLocalIndexI32;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert!(!route.materialized_ordinary_map_owned_any_v2_candidate);
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
        let route_receipt = route
            .ordinary_map_owned_any_v2_values_local_index_i32_route_receipt
            .as_ref()
            .expect("dedicated route receipt");
        route_receipt
            .validate_against_program(&route.program)
            .expect("profile-specific route identity is bound to canonical MIR");
        assert_eq!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_route(
                &checked_program,
                &route.program
            )
            .expect("Checker+MIR validation returns the independent route receipt"),
            *route_receipt
        );

        let contract_checked = checked(
            r#"func main() -> i32 {
    ensures: result == 41
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 0
    let item = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
        );
        let contract_route = materialize_canonical_mir_route(&contract_checked, None)
            .expect("the exact result == 41 Ensures stays within the dedicated route");
        let contract_witness = contract_route
            .program
            .ordinary_map_owned_any_v2_values_local_index_i32_receipts()
            .expect("contract fixture has an exact local-index receipt")
            .into_iter()
            .next()
            .expect("unique local-index receipt");
        validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(
            &contract_route.program,
        )
        .expect("only the ValuesLocalIndexI32 profile admits its exact Ensures predicate");
        let mut changed_ensures = contract_route.program.clone();
        mutate_values_local_index_mir(&mut changed_ensures, &contract_witness, |function| {
            function.contracts[0].condition = crate::core::mir::MirContractExpr::Binary {
                op: crate::core::mir::MirContractBinaryOp::Equal,
                left: Box::new(crate::core::mir::MirContractExpr::Result),
                right: Box::new(crate::core::mir::MirContractExpr::Int(40)),
            };
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&changed_ensures)
                .is_err(),
            "the narrow route rejects an Ensures predicate outside result == 41"
        );
        let mut changed_contract_kind = contract_route.program.clone();
        mutate_values_local_index_mir(&mut changed_contract_kind, &contract_witness, |function| {
            function.contracts[0].kind = crate::core::mir::MirContractKind::Requires;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(
                &changed_contract_kind
            )
            .is_err(),
            "the narrow route does not authorize Requires as its Ensures predicate"
        );
        let mut changed_contract_types = contract_route.program.clone();
        mutate_values_local_index_mir(&mut changed_contract_types, &contract_witness, |function| {
            function.contracts[0].expression_types.insert(
                vec![2],
                crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32),
            );
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(
                &changed_contract_types
            )
            .is_err(),
            "the narrow route rejects extra contract TypeDesc paths"
        );

        let mut injected_nop = route.program.clone();
        mutate_values_local_index_mir(&mut injected_nop, witness, |function| {
            let block = function
                .blocks
                .get_mut(&function.entry)
                .expect("main entry block");
            block.instructions.push(crate::core::mir::MirInstruction {
                id: crate::core::mir::MirInstructionId::new("inst:injected-nop")
                    .expect("valid instruction identity"),
                kind: MirInstructionKind::Nop,
            });
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&injected_nop)
                .is_err(),
            "the narrow structural route rejects an instruction outside its exact graph"
        );
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_route(
                &checked_program,
                &injected_nop
            )
            .is_err()
        );
        let raw_results = crate::verifier::verify_mir(
            &injected_nop,
            "values-local-index-i32-injected-nop".into(),
        )
        .expect("raw V2 MIR falls back to the diagnostic-only island");
        let raw_main = raw_results
            .iter()
            .find(|result| result.func_name.ends_with("main"))
            .expect("raw verifier reports the main owner");
        assert_eq!(
            raw_main.status,
            crate::verifier::VerifStatus::NotInTrustedSubset,
            "raw MIR cannot use ValuesLocalIndexI32 as source-bound verification authority"
        );

        let mut injected_println = route.program.clone();
        mutate_values_local_index_mir(&mut injected_println, witness, |function| {
            let result = crate::core::mir::MirValueId::new("expr:injected-println-unit")
                .expect("valid result identity");
            let unit_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::Unit);
            function.values.insert(
                result.clone(),
                crate::core::mir::MirValue {
                    id: result.clone(),
                    ty: unit_type,
                },
            );
            let block = function
                .blocks
                .get_mut(&function.entry)
                .expect("main entry block");
            block.instructions.push(crate::core::mir::MirInstruction {
                id: crate::core::mir::MirInstructionId::new("inst:injected-println-int")
                    .expect("valid instruction identity"),
                kind: MirInstructionKind::BuiltinCall {
                    result,
                    kind: crate::core::mir::types::MirBuiltinKind::PrintlnInt,
                    arguments: vec![witness.unpack.result_binding.clone()],
                    string_field_contract: None,
                },
            });
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&injected_println)
                .is_err(),
            "the narrow structural route rejects an injected output operation"
        );
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_route(
                &checked_program,
                &injected_println
            )
            .is_err()
        );

        let mut changed_const = route.program.clone();
        mutate_values_local_index_mir(&mut changed_const, witness, |function| {
            let instruction = function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
                .find(|instruction| instruction.id == witness.const_instruction)
                .expect("index Const");
            let MirInstructionKind::Const { literal, .. } = &mut instruction.kind else {
                panic!("exact index initializer instruction is Const")
            };
            *literal = crate::core::ResolvedLiteral::Int(1);
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&changed_const)
                .is_err()
        );

        let mut changed_move = route.program.clone();
        mutate_values_local_index_mir(&mut changed_move, witness, |function| {
            let instruction = function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
                .find(|instruction| instruction.id == witness.binding_instruction)
                .expect("index binding Move");
            let MirInstructionKind::Move { source, .. } = &mut instruction.kind else {
                panic!("exact index binding instruction is Move")
            };
            *source = crate::core::mir::MirValueId::new("expr:forged_index_producer")
                .expect("valid forged test identity");
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&changed_move)
                .is_err()
        );

        let mut changed_operand = route.program.clone();
        mutate_values_local_index_mir(&mut changed_operand, witness, |function| {
            let instruction = function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
                .find(|instruction| instruction.id == witness.unpack.instruction)
                .expect("Values unpack");
            let MirInstructionKind::OrdinaryMapOwnedAnyV2ValuesUnpack { index, .. } =
                &mut instruction.kind
            else {
                panic!("exact index projection is ValuesUnpack")
            };
            *index = witness.const_result.clone();
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_local_index_i32_mir_route(&changed_operand)
                .is_err()
        );
    }

    #[test]
    fn values_local_index_i32_checker_admission_rejects_nearby_source_shapes() {
        let cases = [
            (
                "mutable index",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let mut index: i32 = 0
    let item = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "reassigned index",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let mut index: i32 = 0
    index = 0
    let item = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "aliased index",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 0
    let alias = index
    let item = snapshot[alias] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "computed initializer",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 0 + 0
    let item = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "computed index expression",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 0
    let item = snapshot[index + 0] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "nonzero index",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 1
    let item = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    item
}"#,
            ),
            (
                "extra unpack",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = values(root)
    let index: i32 = 0
    let first = snapshot[index] as i32
    let second = snapshot[index] as i32
    drop(snapshot)
    drop(empty)
    drop(root)
    first + second
}"#,
            ),
        ];
        for (name, source) in cases {
            let candidate = checked(source);
            assert_ne!(
                classify_canonical_mir_route_admission(&candidate).ordinary_map_owned_any_v2,
                OrdinaryMapOwnedAnyV2Admission::ValuesLocalIndexI32,
                "source variation must not acquire the ValuesLocalIndexI32 profile: {name}"
            );
        }
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_field_move_gets_an_independent_route_receipt() {
        let program = checked(include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_values_field_move.mimi"
        ));
        assert_eq!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::ValuesFieldMove
        );
        let canonical = MirProgram::from_checked_program(&program)
            .expect("direct Label field move lowers with exact source-use receipts");
        let owner = NodeId("function:main".into());
        let checker_receipt = &program
            .resource_analysis(&owner)
            .expect("Checker resource analysis")
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("Checker owner-v2 source receipt")
            .values_unpack_receipts[0];
        let mir_receipt = canonical
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("MIR v3 receipt derives")
            .into_iter()
            .next()
            .expect("one selected Label");
        let source_field_move = checker_receipt
            .result_owner_field_move
            .as_ref()
            .expect("Checker field-move receipt");
        let mir_field_move = mir_receipt
            .result_owner_field_move
            .as_ref()
            .expect("MIR field-move result receipt");
        assert_eq!(mir_field_move.source, *source_field_move);
        assert_eq!(source_field_move.text_read_uses.len(), 2);
        assert_eq!(mir_field_move.text_read_uses.len(), 2);
        validate_ordinary_map_owned_any_v2_values_unpack_receipts(&program, &canonical)
            .expect("route compares the complete Checker source receipt with MIR v3");
        validate_ordinary_map_owned_any_v2_values_field_move_route(&program, &canonical)
            .expect("the narrow profile binds the exact literal-index field-move/read set");
        validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&canonical)
            .expect("MIR-only consumers validate the same exact Values field-move graph");

        let route = materialize_canonical_mir_route(&program, None)
            .expect("the independently admitted Values field-move route materializes");
        let profile = CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2ValuesFieldMove;
        assert!(profile.is_admitted(route.admission));
        assert!(profile.is_materialized(&route));
        assert_eq!(profile.as_str(), "map-any-owner-v2-values-field-move-v1");
        assert_eq!(
            route
                .ordinary_map_owned_any_v2_values_field_move_route_receipt
                .as_ref()
                .map(|receipt| receipt.profile.as_str()),
            Some("map-any-owner-v2-values-field-move-v1")
        );
        assert!(
            !route.materialized_ordinary_map_owned_any_v2_candidate,
            "the narrow profile does not materialize broad CompleteCoverage"
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_field_move_rejects_near_miss_indexes() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_values_field_move.mimi"
        );
        let nonzero_index_selecting_label = source
            .replace(
                "    let root = map_set(empty, \"label\", label)\n",
                "    let earlier = map_set(empty, \"alpha\", 17)\n    let root = map_set(earlier, \"label\", label)\n",
            )
            .replace("snapshot[0] as Label", "snapshot[1] as Label")
            .replace(
                "    drop(empty)\n",
                "    drop(empty)\n    drop(earlier)\n",
            );
        for (name, changed) in [
            ("nonzero literal", nonzero_index_selecting_label),
            (
                "local index",
                source.replace(
                    "    let item = snapshot[0] as Label",
                    "    let zero = 0\n    let item = snapshot[zero] as Label",
                ),
            ),
        ] {
            assert_ne!(changed, source, "the {name} mutation must apply");
            let program = checked(&changed);
            let admission = classify_canonical_mir_route_admission(&program);
            assert_ne!(
                admission.ordinary_map_owned_any_v2,
                OrdinaryMapOwnedAnyV2Admission::ValuesFieldMove,
                "the {name} shape is outside the dedicated field-move route"
            );
            let canonical = MirProgram::from_checked_program(&program)
                .expect("near-miss MIR remains structurally valid");
            assert!(
                validate_ordinary_map_owned_any_v2_values_field_move_route(&program, &canonical)
                    .is_err(),
                "the CheckedProgram+MIR gate rejects the {name} shape"
            );
            assert_eq!(
                admission.ordinary_map_owned_any_v2,
                OrdinaryMapOwnedAnyV2Admission::CompleteCoverage,
                "the near miss remains broad coverage and must not borrow the narrow receipt"
            );
            assert!(materialize_canonical_mir_route(&program, None)
                .expect_err("broad V2 readiness remains closed")
                .to_string()
                .contains("production-readiness gate is closed"));
        }
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_field_move_mir_gate_rejects_nonzero_and_dynamic_indexes() {
        use crate::core::ir::ResolvedLiteral;

        let source = values_field_move_mir();
        let unpack = source
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("exact unpack receipt")
            .into_iter()
            .next()
            .expect("one field-move unpack");

        let mut nonzero = source.clone();
        mutate_main_mir(&mut nonzero, |function| {
            let mut changed = false;
            for instruction in function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
            {
                if let MirInstructionKind::Const { result, literal } = &mut instruction.kind {
                    if result == &unpack.index {
                        *literal = ResolvedLiteral::Int(1);
                        changed = true;
                    }
                }
            }
            assert!(changed, "the exact index-zero constant exists");
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&nonzero).is_err(),
            "a nonzero MIR index cannot borrow the field-move profile"
        );

        let mut dynamic = source;
        mutate_main_mir(&mut dynamic, |function| {
            let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
            let dynamic_source = function
                .blocks
                .values()
                .flat_map(|block| &block.instructions)
                .filter_map(|instruction| match &instruction.kind {
                    MirInstructionKind::Const { result, .. }
                        if result != &unpack.index
                            && function.values.get(result).map(|value| &value.ty)
                                == Some(&i32_type) =>
                    {
                        Some(result.clone())
                    }
                    _ => None,
                })
                .next()
                .expect("fixture has another i32 constant for the synthetic dynamic operand");
            let mut changed = false;
            for instruction in function
                .blocks
                .values_mut()
                .flat_map(|block| &mut block.instructions)
            {
                if let MirInstructionKind::Const { result, .. } = &instruction.kind {
                    if result == &unpack.index {
                        instruction.kind = MirInstructionKind::Copy {
                            result: unpack.index.clone(),
                            source: dynamic_source.clone(),
                        };
                        changed = true;
                    }
                }
            }
            assert!(changed, "the exact index-zero constant exists");
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&dynamic).is_err(),
            "a computed MIR index cannot borrow the field-move profile"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_field_move_mir_gate_rejects_receipt_mutations() {
        let source = values_field_move_mir();

        let mut missing_read = source.clone();
        mutate_main_mir(&mut missing_read, |function| {
            let cfg = function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker V2 CFG receipt");
            let field_move = cfg.values_unpack_receipts[0]
                .result_owner_field_move
                .as_mut()
                .expect("Checker field-move receipt");
            field_move.text_read_uses.pop();
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&missing_read).is_err(),
            "an omitted String read cannot be hidden from the MIR-only gate"
        );

        let mut changed_read = source.clone();
        mutate_main_mir(&mut changed_read, |function| {
            let cfg = function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker V2 CFG receipt");
            let read = &mut cfg.values_unpack_receipts[0]
                .result_owner_field_move
                .as_mut()
                .expect("Checker field-move receipt")
                .text_read_uses[0];
            read.not_equal = !read.not_equal;
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&changed_read).is_err(),
            "an altered Eq/Ne read commitment cannot pass"
        );

        let mut wrong_field = source.clone();
        mutate_main_mir(&mut wrong_field, |function| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker V2 CFG receipt")
                .values_unpack_receipts[0]
                .result_owner_field_move
                .as_mut()
                .expect("Checker field-move receipt")
                .field_name = "other".into();
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&wrong_field).is_err(),
            "the field-move route is specific to Label.text"
        );

        let mut wrong_drop = source.clone();
        mutate_main_mir(&mut wrong_drop, |function| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("Checker V2 CFG receipt")
                .values_unpack_receipts[0]
                .result_owner_field_move
                .as_mut()
                .expect("Checker field-move receipt")
                .text_settlement_point = NodeId("forged-string-drop".into());
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&wrong_drop).is_err(),
            "the exact moved String Drop point is mandatory"
        );

        let mut missing_root_drop = source.clone();
        let root_drop = missing_root_drop
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2
            .iter()
            .find(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::Drop)
            .expect("one root settlement action")
            .instruction
            .clone();
        mutate_main_mir(&mut missing_root_drop, |function| {
            for block in function.blocks.values_mut() {
                block
                    .instructions
                    .retain(|instruction| instruction.id != root_drop);
            }
        });
        assert!(
            validate_ordinary_map_owned_any_v2_values_field_move_mir_route(&missing_root_drop)
                .is_err(),
            "both persistent Map roots must retain their exact Drop settlements"
        );
    }

