    #[test]
    fn ordinary_map_owned_any_v2_empty_root_admission_follows_checker_lineage() {
        let set_result_is_queried = checked(
            r#"
func main() -> i32 {
    let prefix = "answer\0雪"
    let key = prefix + "!"
    let empty = map_new()
    let inserted = map_set(empty, key, 41)
    let pair = map_get(inserted, prefix + "!")
    let found = pair.0
    drop(pair)
    drop(empty)
    drop(inserted)
    drop(key)
    drop(prefix)
    if found { 1 } else { 0 }
}
"#,
        );
        let analysis = set_result_is_queried
            .resource_analysis(&NodeId("function:main".into()))
            .expect("primitive Map attempt analysis");
        let set_attempt = analysis
            .ordinary_map_owned_any_v2_operation_attempts
            .iter()
            .find(|attempt| attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Set)
            .expect("Set attempt remains for the primitive Map family");
        let get_any_attempt = analysis
            .ordinary_map_owned_any_v2_operation_attempts
            .iter()
            .find(|attempt| attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::GetAny)
            .expect("GetAny attempt remains for the computed String key");
        assert_eq!(
            get_any_attempt.receiver_local, set_attempt.result_local,
            "the query observes the Set successor root"
        );
        assert_eq!(
            analysis
                .ordinary_map_owned_any_v2_actions
                .iter()
                .find(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::GetAny)
                .and_then(|action| action.key_provenance),
            Some(crate::core::OrdinaryMapOwnedAnyV2KeyProvenance::ComputedString),
            "the computed key is validly receipted even though its primitive Set family is outside V2"
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&set_result_is_queried)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::OutsideProfile,
            "a persistent Set -> GetAny chain that only reads pair.0 remains V1-owned traffic"
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&set_result_is_queried)
                .ordinary_map_owned_get_i32_string_v1,
            OrdinaryMapOwnedGetI32StringV1Admission::CompleteCoverage,
            "the same primitive owner chain has a complete historical V1 receipt"
        );
        let route = materialize_canonical_mir_route(&set_result_is_queried, None)
            .expect("pair-flag-only GetAny keeps its valid V1 owned-get route");
        assert!(CanonicalMirRouteProfile::OrdinaryMapOwnedGetI32StringV1.is_materialized(&route));

        let set_result_is_not_queried = checked(
            r#"
func main() -> i32 {
    let root = map_new()
    let pair = map_get(root, "answer")
    let found = pair.0
    drop(pair)
    let successor = map_set(root, "later", 1)
    drop(root)
    drop(successor)
    if found { 1 } else { 0 }
}
"#,
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&set_result_is_not_queried)
                .ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "a later Set successor does not erase the earlier empty-root query signal"
        );
    }

    #[test]
    fn persistent_primitive_get_any_requires_a_direct_v2_value_intent() {
        for (label, source) in [
            (
                "snapshot escape",
                r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "key", "value")
    let pair = map_get(root, "key")
    drop(empty)
    drop(root)
    let found = pair.0
    drop(pair)
    if found { 1 } else { 0 }
}
"#,
            ),
            (
                "Any/String equality",
                r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "key", "value")
    let pair = map_get(root, "key")
    drop(empty)
    drop(root)
    let equal = pair.1 == "value"
    drop(pair)
    if equal { 0 } else { 1 }
}
"#,
            ),
        ] {
            let program = checked(source);
            let admission = classify_canonical_mir_route_admission(&program);
            assert_eq!(
                admission.ordinary_map_owned_any_v2,
                OrdinaryMapOwnedAnyV2Admission::OutsideProfile,
                "persistent primitive GetAny {label} remains outside V2"
            );
            assert_eq!(
                admission.ordinary_map_owned_get_i32_string_v1,
                OrdinaryMapOwnedGetI32StringV1Admission::CompleteCoverage,
                "persistent primitive GetAny {label} retains its V1 owner receipt"
            );
            let route = materialize_canonical_mir_route(&program, None)
                .unwrap_or_else(|error| panic!("V1 {label} route must materialize: {error}"));
            assert!(
                CanonicalMirRouteProfile::OrdinaryMapOwnedGetI32StringV1.is_materialized(&route)
            );
        }

        let malformed_v2_intent = checked(
            r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "key", 42)
    let pair = map_get(root, "key")
    let payload = unpack_i32(pair.1)
    let all_keys = keys(root)
    let count = all_keys.len()
    drop(all_keys)
    drop(pair)
    drop(empty)
    drop(root)
    payload + count
}
"#,
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&malformed_v2_intent).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "direct DynamicAnyUnpack from a Set-successor GetAny keeps an unsupported V2 graph visible"
        );
        assert!(matches!(
            materialize_canonical_mir_route(&malformed_v2_intent, None),
            Err(CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                ..
            })
        ));
    }

