    #[test]
    fn public_route_materializer_rejects_complete_v2_until_production_readiness_opens() {
        let program = checked(
            r#"
type Label { text: string }
func main() -> i32 {
    let label = Label { text: "owned label" }
    let empty = map_new()
    let root = map_set(empty, "label", label)
    drop(empty)
    drop(root)
    drop(label)
    0
}
"#,
        );
        assert_eq!(
            classify_canonical_mir_route_admission(&program).ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::CompleteCoverage
        );
        assert!(!ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);

        let error = materialize_canonical_mir_route(&program, None)
            .expect_err("complete coverage is diagnostic-only until the shared ready gate opens");
        assert!(matches!(
            error,
            CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                ..
            }
        ));
        assert!(error
            .to_string()
            .contains("production-readiness gate is closed"));

        let diagnostic =
            materialize_ordinary_map_owned_any_v2_for_verifier_diagnostics(&program, None)
                .expect("internal verifier diagnostics can still inspect complete V2 MIR");
        assert!(diagnostic.program.functions().values().any(|function| {
            function
                .ownership
                .has_checker_ordinary_map_owned_any_v2_actions()
        }));
    }

    #[test]
    fn scalar_generic_argument_projection_binds_checker_signature_to_body_formals() {
        let program = checked(
            "func pick<T>(a: T, b: T, c: T) -> T { c }\nfunc main() -> i32 { pick(41, 42, 43) }",
        );
        let callable = program
            .callable(&NodeId("function:pick".into()))
            .expect("checked generic callable");
        assert_eq!(
            crate::core::mir::scalar_generic_argument_projection(&program, callable),
            Some((2, 3))
        );
        let mut reordered = callable.clone();
        reordered.body.parameters.swap(0, 2);
        assert_eq!(
            crate::core::mir::scalar_generic_argument_projection(&program, &reordered),
            None,
            "the projection index cannot be derived from a mismatched signature/body ordering"
        );
        let mut duplicate = callable.clone();
        duplicate.body.parameters[1] = duplicate.body.parameters[2].clone();
        assert_eq!(
            crate::core::mir::scalar_generic_argument_projection(&program, &duplicate),
            None,
            "duplicate body formal identities cannot authorize a projection"
        );
    }

    #[test]
    fn scalar_generic_identity_admission_is_exact_and_materializes_a_closed_route() {
        let program =
            checked("func pass<T>(value: T) -> T { value }\nfunc main() -> i32 { pass(41) }");
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.scalar_generic_identity_i32,
            ScalarGenericIdentityAdmission::CompleteCoverage
        );
        let route = materialize_canonical_mir_route(&program, None)
            .expect("exact scalar generic identity route must materialize");
        assert!(CanonicalMirRouteProfile::ScalarGenericIdentityI32.is_admitted(admission));
        assert!(CanonicalMirRouteProfile::ScalarGenericIdentityI32.is_materialized(&route));
        crate::core::mir::validate_scalar_generic_identity_island(&route.program)
            .expect("materialized scalar generic identity route must validate");

        let projected_i32 = checked(
            "func choose<T>(left: T, right: T) -> T { left }\nfunc main() -> i32 { choose(41, 43) }",
        );
        let projected_i32_admission = classify_canonical_mir_route_admission(&projected_i32);
        assert_eq!(
            projected_i32_admission.scalar_generic_identity_i32,
            ScalarGenericIdentityAdmission::CompleteCoverage
        );
        let projected_i32_route = materialize_canonical_mir_route(&projected_i32, None)
            .expect("argument projection i32 route must materialize");
        let projected_i32_instance = projected_i32_route
            .program
            .instances()
            .values()
            .next()
            .expect("argument projection instance");
        assert_eq!(
            projected_i32_instance.contract,
            crate::core::mir::MirGenericInstanceContract::ScalarArgumentProjection {
                parameter_index: 0,
                parameter_count: 2,
            }
        );
        crate::core::mir::validate_scalar_generic_identity_island(&projected_i32_route.program)
            .expect("argument projection i32 route must validate");

        let projected_i64 = checked(
            "func choose<T>(left: T, right: T) -> T { left }\nfunc main() -> i64 { choose(2147483690, 2147483691) }",
        );
        let projected_i64_admission = classify_canonical_mir_route_admission(&projected_i64);
        assert_eq!(
            projected_i64_admission.scalar_generic_identity_i64,
            ScalarGenericIdentityAdmission::CompleteCoverage
        );
        let projected_i64_route = materialize_canonical_mir_route(&projected_i64, None)
            .expect("argument projection i64 route must materialize");
        crate::core::mir::validate_scalar_generic_identity_i64_island(&projected_i64_route.program)
            .expect("argument projection i64 route must validate");

        for source in [
            "func pass<T>(value: T) -> T { value }\nfunc main() -> bool { pass(true) }",
            "func pass<T>(value: T) -> T { value }\nfunc helper() -> i32 { 0 }\nfunc main() -> i32 { pass(41) }",
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i32 { pass(pass(41)) }",
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i32 { requires: true; pass(41) }",
            "func choose<T>(left: T, right: T) -> T { let chosen = right; chosen }\nfunc main() -> i32 { choose(41, 43) }",
            "func choose<T>(left: T, right: T) -> T { left }\nfunc helper() -> i32 { 0 }\nfunc main() -> i32 { choose(41, 43) }",
        ] {
            let program = checked(source);
            assert_eq!(
                classify_scalar_generic_identity_admission(&program),
                ScalarGenericIdentityAdmission::OutsideProfile,
                "unsupported source shape must remain outside the exact identity profile: {source}"
            );
        }

        let i64_program = checked(
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i64 { pass(2147483690) }",
        );
        let i64_admission = classify_canonical_mir_route_admission(&i64_program);
        assert_eq!(
            i64_admission.scalar_generic_identity_i32,
            ScalarGenericIdentityAdmission::OutsideProfile
        );
        assert_eq!(
            i64_admission.scalar_generic_identity_i64,
            ScalarGenericIdentityAdmission::CompleteCoverage
        );
        let i64_route = materialize_canonical_mir_route(&i64_program, None)
            .expect("exact i64 scalar generic identity route must materialize");
        assert!(CanonicalMirRouteProfile::ScalarGenericIdentityI64.is_admitted(i64_admission));
        assert!(CanonicalMirRouteProfile::ScalarGenericIdentityI64.is_materialized(&i64_route));
        crate::core::mir::validate_scalar_generic_identity_i64_island(&i64_route.program)
            .expect("materialized i64 scalar generic identity route must validate");

        for source in [
            "func pass<T>(value: T) -> T { value }\nfunc main() -> bool { pass(true) }",
            "func pass<T>(value: T) -> T { value }\nfunc helper() -> i64 { 0 }\nfunc main() -> i64 { pass(41) }",
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i64 { pass(41) }",
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i64 { pass(pass(41)) }",
            "func pass<T>(value: T) -> T { value }\nfunc main() -> i64 { requires: true; pass(2147483690) }",
            "func choose<T>(left: T, right: T) -> T { right }\nfunc main() -> i64 { choose(41, 43) }",
        ] {
            let program = checked(source);
            assert_eq!(
                classify_scalar_generic_identity_i64_admission(&program),
                ScalarGenericIdentityAdmission::OutsideProfile,
                "unsupported source shape must remain outside the exact i64 identity profile: {source}"
            );
        }
    }

    #[test]
    fn ordinary_scalar_contract_admission_preserves_unmigrated_and_no_contract_faces() {
        let admitted = checked(
            "func yes(flag: bool) -> bool { ensures: result == flag
 flag } func main() -> i32 { if yes(true) { 42 } else { 0 } }",
        );
        let route =
            materialize_canonical_mir_route(&admitted, None).expect("scalar contract route");
        assert!(route.admission.collection_complete());
        assert!(route.materialized_collection_candidate);
        assert!(!route.materialized_collection_operation_candidate);
        for source in [
            "func main() -> i32 { 42 }",
            "func recur(value: i32) -> i32 { ensures: result >= 0
 if value == 0 { 0 } else { recur(value - 1) } } func main() -> i32 { 0 }",
            "func yes() -> bool { ensures: result == true
 true } func main() -> i32 { let mut n = 0
 while n < 2 { n = n + 1 }
 n }",
            "func yes() -> bool { ensures: result == true
 true } func text(value: string) -> string { value } func main() -> i32 { 0 }",
            "func lemma(value: i32) -> i32 { requires: value > 0
 math: { value > 0 }
 ensures: result > 0
 value } func main() -> i32 { 0 }",
            "func guarded(value: i32) -> i32 { requires: value > 0
 invariant: value > 0
 ensures: result > 0
 value } func main() -> i32 { 0 }",
        ] {
            assert_eq!(
                classify_canonical_mir_route_admission(&checked(source)).collection,
                ScalarCollectionAdmission::OutsideProfile,
                "a contract must not promote an unrelated compatibility body: {source}"
            );
        }
    }

