    #[test]
    fn ordinary_map_owned_get_values_scope_cleanup_does_not_settle_result_owner() {
        let program = checked(
            r#"
                func main() -> i32 {
                    let root = map_new()
                    let snapshot = values(root)
                    let count = snapshot.len()
                    drop(root)
                    count
                }
            "#,
        );
        let admission = classify_canonical_mir_route_admission(&program);
        assert_eq!(
            admission.ordinary_map_owned_get_i32_string_v1,
            OrdinaryMapOwnedGetI32StringV1Admission::CompleteCoverage,
            "the V1 observation remains complete, but it cannot bypass the incomplete V2 owner candidate"
        );
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
            "scope cleanup is not a V2 result-owner settlement"
        );

        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("Checker resource analysis");
        let v1_cfg_receipt = analysis
            .ordinary_map_owned_get_i32_string_v1_cfg_receipt
            .as_ref()
            .expect("V1 owned-get Checker receipt for Values");
        let values_result = v1_cfg_receipt
            .result_receipts
            .iter()
            .find(|result| {
                result.kind == crate::core::OrdinaryMapOwnedGetI32StringV1ActionKind::Values
            })
            .expect("V1 Values result-owner receipt");
        let values_binding = values_result
            .binding
            .as_ref()
            .expect("Values result binding");
        assert_eq!(
            values_result.settlement,
            crate::core::OrdinaryMapOwnedGetResultSettlementKind::Unsettled,
            "observing the Values result does not settle its aggregate owner"
        );
        assert!(!values_result.settlement.is_receipted());
        assert!(!analysis
            .ordinary_map_owned_get_i32_string_v1_actions
            .iter()
            .any(|action| {
                action.kind == crate::core::OrdinaryMapOwnedGetI32StringV1ActionKind::Drop
                    && &action.local == values_binding
            }));
        assert!(analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none());
        assert!(analysis
            .ordinary_map_owned_any_v2_operation_attempts
            .iter()
            .any(|attempt| {
                attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Values
                    && attempt.result_local.as_ref() == Some(values_binding)
            }));
        assert!(!analysis
            .ordinary_map_owned_any_v2_operation_attempts
            .iter()
            .any(|attempt| {
                attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::ScopeDrop
                    && attempt.receiver_local.as_ref() == Some(values_binding)
            }));
        assert!(!analysis
            .ordinary_map_owned_any_v2_actions
            .iter()
            .any(|action| {
                action.kind == OrdinaryMapOwnedAnyV2ActionKind::Drop
                    && &action.local == values_binding
            }));

        let error = materialize_canonical_mir_route(&program, None)
            .expect_err("scope cleanup must not discharge a Values result owner");
        match error {
            CanonicalMirRouteMaterializationError::Complete {
                profile: CanonicalMirRouteProfile::OrdinaryMapOwnedAnyV2,
                stage: CanonicalMirRouteFailureStage::Coverage,
                message,
            } => assert!(
                message.contains("withheld complete operation-attempt coverage"),
                "{message}"
            ),
            other => panic!("scope-only Values result must fail at coverage, got {other:?}"),
        }
    }

